window.LINES = {
  // ================================================================ the engine's own: things that don't work
  alan_fail_01: ['alan', "No. Even on holiday, no."],
  alan_fail_02: ['alan', "That's not how anything works. I've sold the manuals."],
  alan_fail_03: ['alan', "Interesting idea. Wrong, but interesting. Like my twenties."],
  alan_fail_04: ['alan', "No. And I say that as a man who has said yes to a lot of bad ideas."],
  alan_fail_05: ['alan', "If that worked, someone in my family would have done it already. Probably with a bell."],
  alan_fail_06: ['alan', "I'm improvising, not hallucinating. It's the heat."],
  alan_fail_07: ['alan', "Inês would make a face. I can feel her making it from Lisbon."],
  alan_fail_08: ['alan', "Not unless I want to explain myself to the Guardia Civil in my third language."],
  alan_fail_09: ['alan', "I'm sunburnt, not desperate. [pause] Not that desperate."],
  alan_fail_10: ['alan', "That would be a story. A short, stupid story."],
  alan_fail_look: ['alan', "Nothing there I can use. Nothing anywhere I can use, some days."],
  alan_fail_talk: ['alan', "It's not much of a conversationalist."],
  alan_fail_take: ['alan', "I don't need that. I barely need half of what I've got, and the airline has the other half."],
  alan_def_item: ['alan', "Those two have nothing to say to each other."],
  alan_npc_busy: ['alan', "They're busy. Somebody on this island has to be."],
  alan_fail_carmen_item: ['carmen', "If it isn't a cigarette or a reason, don't show it to me."],
  alan_fail_baute_item: ['baute', "Keep it, Mr. Sanches. I have more than enough of other people's things."],
  alan_fail_nieves_item: ['nieves', "The hotel can't keep that for you, señor. Or won't."],
  alan_fail_rafa_item: ['rafa', "Cute. Put it away."],
  alan_fail_phone_item: ['alan', "It takes coins. Only coins. The one honest machine on the island."],
  vasco_fail_01: ['vasco', "No."],
  vasco_fail_02: ['vasco', "That isn't how stone works. I've spent twenty years asking it."],
  vasco_fail_03: ['vasco', "Alan would try that. [pause] I'm not thinking about Alan."],
  vasco_fail_04: ['vasco', "Pointless. Patient, but pointless."],
  vasco_fail_05: ['vasco', "The dead wouldn't thank me for that."],
  vasco_fail_06: ['vasco', "Think first. Then touch. In that order."],
  vasco_fail_07: ['vasco', "No. Not with that."],
  vasco_fail_08: ['vasco', "A good idea, in a different century."],
  vasco_fail_09: ['vasco', "I'd only be doing it to feel busy."],
  vasco_fail_10: ['vasco', "No. Read it again."],
  vasco_fail_look: ['vasco', "Nothing. Recent, and nothing."],
  vasco_fail_talk: ['vasco', "It hasn't spoken in nine hundred years. It won't start for me."],
  vasco_fail_take: ['vasco', "It belongs where it is. Most things do."],
  vasco_def_item: ['vasco', "They don't go together."],
  vasco_npc_busy: ['vasco', "Busy. Leave them."],
  narr_death: ['narr', "The water rises, and closes, and keeps what it is given."],

  // ================================================================ PROLOGUE: 21 December 1995
  carmen_machine: ['carmen', "Trujillo. Speak, or don't."],
  elena_msg_01: ['elena', "Carmen. It's me. I know it's late. [pause] Somebody's taken one of the discs out of the channel. The wear marks are fresh. It isn't conservation."],
  elena_msg_02: ['elena', "And it isn't a calendar either. I've been reading it wrong for a year. [pause] It's a door, Carmen. And someone's opening it."],
  elena_msg_03: ['elena', "I'm driving down now. Don't smoke all of them before I get there. [pause] Te quiero."],
  barman_stay: ['barman', "There's cloud on the road, doctora. Stay."],
  elena_stay: ['elena', "There's always cloud on the road."],
  narr_pro_road: ['narr', "The road down from Artenara, ten past midnight. Below, the winter sea of cloud lies silver under the moon."],
  elena_look_radio: ['elena', "Radio Las Palmas. Still awake. Someone has to be."],
  elena_use_radio: ['elena', "A timple, and a woman singing. Leave it. It's company."],
  elena_look_radio_2: ['elena', "Static. And under the static, surf. [pause] There's no surf up here."],
  elena_look_notebook: ['elena', "Seven circles in a line. One shaded empty. [pause] Six. There should be seven."],
  elena_look_mirror: ['elena', "The camp lights, going out one by one. Rayco's still up. He never sleeps."],
  elena_look_mirror_2: ['elena', "Nothing behind me. Nothing at all."],
  elena_look_crank: ['elena', "The window crank. It sticks, like everything in this car."],
  elena_use_crank: ['elena', "An inch. Cold air, and pine. [pause] Smells like mountains. Good."],
  elena_crank_stuck: ['elena', "It won't turn. Come on. Come on."],
  elena_crank_stuck_look: ['elena', "The handle's wet. Why is the handle wet?"],
  narr_pro_cloud: ['narr', "The car goes into the cloud. The world turns grey, and then quiet."],
  elena_look_air: ['elena', "Salt. [pause] Why is it salt?"],
  elena_salt: ['elena', "Water on the inside of the glass. On the inside."],
  elena_doors: ['elena', "The doors. [pause] No. It's a door, Carmen. I told you it was a door."],
  gc_01: ['gc1', "Flash flood. Has to be."],
  gc_02: ['gc2', "There's no water in this barranco."],
  gc_03: ['gc1', "Then it went somewhere."],
  narr_open_01: ['narr', "The Guardia Civil said it was a flash flood."],
  narr_open_02: ['narr', "It hadn't rained on that side of the mountain for forty days."],

  // ================================================================ TUESDAY 18 JUNE: arrival
  narr_tue_1: ['narr', "Alan Sanches had been on Gran Canaria for fifty-five minutes, and in that time he had lost his luggage, his dignity, and the skin on the back of his neck."],
  narr_t_gando_2: ['narr', "The luggage was in Madrid. The woman at the Iberia desk had told him so with enormous sympathy and no urgency at all, as if Madrid were a place suitcases went to retire."],
  alan_t_land: ['alan', "It would come tomorrow, she said. Or Thursday. It's June, she said, as though that explained it. [pause] Perhaps on Gran Canaria it does."],
  narr_t_vasco_1: ['narr', "Vasco had been on the island for a week. A week was apparently all it took. He was radiant. There was no other word. He was lit up from inside like a church on a feast day."],
  narr_t_kiss: ['narr', "He kissed him, quickly and firmly, on the mouth, in front of a taxi driver, two nuns and a family from Düsseldorf."],
  alan_look_belt: ['alan', "The belt goes round. My suitcase doesn't. It's having a lovely time in Madrid without me."],
  alan_use_belt: ['alan', "I'll wait one more lap. [pause] That was the lap. It's gone."],
  alan_use_belt_2: ['alan', "I'm not watching it again. I have some pride. Not much. Some."],
  alan_look_board: ['alan', "Madrid, Lisbon, Düsseldorf, Manchester. Half of Europe comes here to turn pink. I've made a start."],
  alan_look_vasco_gando: ['alan', "Vasco. A week on the island and he's brown already. He looks like a man who's slept four hours a night and never been happier in his life."],
  alan_taxi_wait: ['alan', "Not without Vasco. He's here somewhere, looking pleased with himself."],
  vasco_t_hello: ['vasco', "You're here."],
  alan_t_hello: ['alan', "I'm here. My trousers are not entirely here. My suitcase is in Madrid."],
  vasco_t_sunburn: ['vasco', "[pause] You're burnt."],
  vasco_t_sorry: ['vasco', "I know. I'm sorry. We found something at the back of Cave 6 this morning. A second channel, very small. I think it's for the equinox, and I couldn't leave until we'd drawn it."],
  alan_t_luggage: ['alan', "I've been standing here for twenty minutes."],
  vasco_t_luggage: ['vasco', "Madrid."],
  alan_t_cave: ['alan', "Rayco."],
  vasco_t_rayco: ['vasco', "Dr. Baute. The director. You'll meet him tonight."],
  alan_t_rayco: ['alan', "You call him Rayco."],
  vasco_t_rayco_2: ['vasco', "[pause] He asked me to."],
  vasco_t_cave: ['vasco', "You'll see it. Not tomorrow. Thursday, perhaps. Rayco wants everything recorded before anyone else goes in."],
  vasco_t_light: ['vasco', "Alan, the light. Wait until you see what the light does in there. It comes in through the roof like a blade and walks across the wall all afternoon, and every engraving it touches, it's like someone reading a sentence out loud."],
  alan_t_proud: ['alan', "Of course he did."],
  vasco_t_go: ['vasco', "Come on. The hotel's on the beach. It isn't a good hotel. You'll love it."],
  narr_t_drive_1: ['narr', "It had been blue sky at the airport. Halfway to Las Palmas they drove under the edge of the cloud, and the light changed as if someone had closed a lid."],
  alan_t_rain: ['alan', "Is it going to rain?"],
  vasco_t_panza_1: ['vasco', "It never rains. It's the panza de burro. The donkey's belly."],
  vasco_t_panza_2: ['vasco', "Every June the trade winds pile the cloud up against the north of the island, and it just sits there. Down in the city it's grey and warm and close, like living in a steam room. And up in the mountains, above it, it's blazing sun."],
  vasco_t_panza_3: ['vasco', "Every morning I drive up through it. Ten minutes of fog, and then you come out on top, and the whole cloud is underneath you like a white sea. All the way to the horizon. [pause] You'll see it."],
  alan_t_thursday: ['alan', "Thursday, perhaps."],
  narr_t_drive_2: ['narr', "Vasco heard it. He was quiet for a moment. Then he reached over and put his hand on Alan's knee, on the split seam, and left it there for the rest of the drive."],
  narr_t_hotel_1: ['narr', "The hotel was not a good hotel. It had rattan chairs and potted palms, a faded poster for the Fiestas de San Juan, and a lift that announced each floor with a sound like a sneeze."],
  narr_t_hotel_2: ['narr', "The expedition had booked it because it was cheap, and the owner sponsored the dig."],
  vasco_t_lobby_1: ['vasco', "There's a reception tonight. At the museum. Jacket required."],
  vasco_t_lobby_3: ['vasco', "I'm going up to change. Eight o'clock, El Museo Canario. [pause] Please don't be late. It matters, this one."],
  alan_lift_tue: ['alan', "No point going up. Everything I own is in Madrid. I need a jacket first."],
  alan_lift_call: ['alan', "Not yet. One more call first. Inês should know."],
  alan_look_lifts: ['alan', "The lift. It announces each floor with a sound like a sneeze. I like it already. It's the only thing here that's as tired as I am."],
  alan_look_nieves: ['alan', "Nieves. A bun so tight it looks structural, and an eyebrow that could run the hotel on its own."],
  alan_look_nieves_sat: ['alan', "She saw me come in. In last night's shirt. The eyebrow saw too."],
  nieves_t_hello: ['nieves', "Señor Sanches. Welcome. [pause] Your luggage has not arrived."],
  alan_t_nieves_1: ['alan', "No."],
  nieves_t_1: ['nieves', "And you have."],
  narr_t_eyebrow: ['narr', "Her eyes travelled down to his trousers, and paused there, and came back up. One eyebrow rose about two millimetres. It was the most eloquent eyebrow Alan had ever seen."],
  nieves_t_box: ['nieves', "Lost and found. [pause] The Germans leave a great many jackets. They arrive in jackets, and then they discover the weather."],
  alan_ask_lostfound: ['alan', "I don't suppose the hotel has a lost and found? Somewhere I might find a jacket that's lost its way?"],
  nieves_lostfound: ['nieves', "Lost property is returned to its owner, señor. The owner describes it. That is how we know he is the owner."],
  alan_look_lostfound: ['alan', "Four jackets. A ski anorak, a child's, a linen thing that's been on a smaller man. And a navy blazer with brass buttons. Beautiful. It isn't mine. Yet."],
  alan_look_lostfound_2: ['alan', "Odd socks, a snorkel and someone's novel with the last chapter torn out. Merciful."],
  alan_use_lostfound: ['alan', "Not with Nieves watching. She'd have me in the lost and found."],
  alan_claim_blazer: ['alan', "I seem to have lost a blazer. Navy. Brass buttons. Very sad about it."],
  nieves_pocket: ['nieves', "Of course, señor. And in the pocket?"],
  alan_pocket_cigar: ['alan', "A cigar band. Montecristo. I've given them up, I keep the bands for the memories."],
  alan_pocket_dignity: ['alan', "My dignity."],
  nieves_pocket_dignity: ['nieves', "We don't keep that, señor. Nobody hands it in."],
  alan_pocket_nothing: ['alan', "Nothing at all. I'm a minimalist."],
  nieves_pocket_nothing: ['nieves', "Then it isn't yours, señor."],
  nieves_blazer_ok: ['nieves', "[pause] Montecristo. Of course. [pause] Please return it to us when you are found, señor."],
  narr_t_sleeves: ['narr', "He put it on. The sleeves stopped a good two inches above his wrists. Nieves looked at him for a long moment."],
  nieves_t_elegant: ['nieves', "Very elegant."],
  alan_blazer_on: ['alan', "I'll stand up straight. I'll be a whole new man. [pause] A whole new man with short arms."],
  alan_look_blazer: ['alan', "Navy, brass buttons, a smell of cigars. Somebody rich lost this. Somebody rich enough not to notice."],
  alan_look_blazer_on: ['alan', "I look like a man who owns a yacht and argues with it."],
  alan_ask_nieves_island: ['alan', "Is it always this grey in June? I was promised sun."],
  nieves_island: ['nieves', "June is the panza de burro, señor. The donkey's belly. Grey on the coast, sun on the mountain. You have to go up for the sun."],
  alan_bye_nieves: ['alan', "Thank you, Nieves."],
  nieves_bye: ['nieves', "Señor."],
  alan_look_gail: ['alan', "English. Pink shoulders, a sun hat, a paperback with a man in an open shirt on the cover. Living my dream."],
  alan_look_derek: ['alan', "Union Jack shorts, socks with sandals, and a camcorder he points at things the way other men point at dogs."],
  gail_t_1: ['gail', "Oh, you're Portuguese! We did Portugal. Didn't we, Derek? Lovely tiles."],
  derek_t_1: ['derek', "Too many hills."],
  gail_t_2: ['gail', "Are you here for the beach? Mind the blazers, they go missing. A gentleman left a lovely navy one on the terrace on Saturday, Derek nearly walked off with it. It smelled of cigars. Cuban. Montecristo, Derek said."],
  alan_t_gail: ['alan', "Derek knows his cigars."],
  gail_t_again: ['gail', "Have you tried the papas arrugadas? Wrinkly potatoes. Derek won't."],
  derek_t_2: ['derek', "Forty quid this camcorder. And she won't let me film anything interesting."],
  alan_t_derek: ['alan', "Film the sea. It's very interesting at the moment. Trust me."],
  alan_look_fax_machine: ['alan', "A fax machine, behind the desk. The hotel's window on the world, and Nieves holds the key."],
  alan_use_fax_machine: ['alan', "I can't fax air. I need something to send. And Nieves to press the button."],
  alan_look_house_phone: ['alan', "The house phone. For room service and complaints. I could use both."],
  alan_use_house_phone: ['alan', "Room service? No. I'll save my pesetas for Inês."],
  alan_look_vasco_room: ['alan', "Vasco, on the bed, reading. He reads in bed like other men breathe."],
  alan_look_window_1: ['alan', "The sea, the beach, the grey lid of cloud. And a bonfire, half built, for something."],
  alan_look_window_2: ['alan', "The beach, a morning. Two bonfires now. They're building them like they mean it."],
  alan_look_window_3: ['alan', "Grey again. The tide's higher than it was. I'm noticing tides. That's never a good sign."],
  alan_look_window_4: ['alan', "The solstice. The longest day, and it's starting grey."],
  alan_look_window_5: ['alan', "I can't look at the sea this morning. It's looking back."],
  alan_look_window_6: ['alan', "The last plane home is at four. The bonfires are taller than the lifeguard tower."],
  alan_look_window_7: ['alan', "The city's birthday. Everyone down there thinks it's an ordinary day."],
  alan_look_bed: ['alan', "The bed. Eight months of sharing one and I still sleep on the edge, like a guest."],
  alan_look_bed_sat: ['alan', "Made. Nobody slept in it. Nobody was here to."],
  alan_use_bed: ['alan', "Not now. If I lie down I'll think, and I've been avoiding that all week."],
  alan_look_fieldbag: ['alan', "Vasco's field bag. Trowels, brushes, notebooks, a compass and one apple. The man is a monk with a mortgage."],
  alan_look_vnote: ['alan', "'Up at the dig. Don't get sunburnt. Again. V.' [pause] He put a kiss and crossed it out and put it back."],
  alan_look_packed: ['alan', "My bag. Packed. The plane's at four. It would be so easy."],
  alan_door_fight: ['alan', "Not now. He's talking. For once I should listen."],
  alan_door_choice: ['alan', "I have to decide first. Where I'm going. Who I am, roughly."],
  alan_look_chano: ['alan', "A round man with a magnificent moustache and a transistor radio held to one ear. He's listening to the football and watching everything else."],
  alan_look_kiosk: ['alan', "Newspapers pegged on a line, sweets, cigarettes, postcards of the beach looking sunnier than the beach."],
  chano_hello: ['chano', "I'm Chano. [pause] You buy a newspaper, I give you a good rate. You don't buy a newspaper, I give you the tourist rate."],
  narr_t_canteras_1: ['narr', "Las Canteras: a long curve of golden beach, a stone promenade the length of it, and a reef a few hundred metres out that broke the Atlantic into lazy, harmless waves."],
  narr_t_canteras_2: ['narr', "On the corner, by a phone box, stood a little green kiosk hung with newspapers pegged on a line like washing."],
  alan_t_chano_1: ['alan', "I need change. For the telephone. To call Lisbon."],
  chano_t_lisbon: ['chano', "Lisbon. [pause] That's a lot of coins."],
  alan_t_chano_2: ['alan', "I know."],
  chano_t_doctor: ['chano', "You're with the doctor. The Portuguese doctor, at the dig. The one who smiles."],
  alan_t_chano_3: ['alan', "How do you know that?"],
  alan_ask_change: ['alan', "Could you break a five-thousand note? I need coins for the phone."],
  alan_buy_paper: ['alan', "I'll buy a newspaper."],
  chano_change: ['chano', "Good. Six coins for the box. [pause] Now I tell you a secret, for free."],
  chano_t_secret: ['chano', "Don't swim after dark this week."],
  alan_t_chano_why: ['alan', "Why not?"],
  chano_t_knees: ['chano', "The sea's in a bad mood. My knees can tell."],
  chano_coins: ['chano', "Keep them for the phone. It's hungrier than me."],
  chano_any: ['chano', "I don't buy, cariño. I only sell. And gossip."],
  alan_ask_change_again: ['alan', "I'm out of coins again. Lisbon is very talkative."],
  chano_change_again_1: ['chano', "Four more. Tell her she's lucky."],
  chano_change_again_2: ['chano', "Four coins. You know, a postcard is cheaper. And it doesn't talk back."],
  chano_change_again_3: ['chano', "Again? Four. Pepe Santana used to buy his paper here. [pause] Four coins."],
  chano_change_again_4: ['chano', "Four. You look like a man who needs to talk to someone. Good. Talk."],
  chano_change_again_5: ['chano', "Four. And on the house, a little advice: eat something."],
  chano_change_again_6: ['chano', "Four. For the last day. If it's the last day."],
  alan_ask_paper: ['alan', "Today's paper, please."],
  chano_paper: ['chano', "La Provincia. All the news that fits."],
  alan_ask_gossip: ['alan', "What's the news that doesn't fit?"],
  chano_gossip_1: ['chano', "The museum is having a party for its rich friends. Montesdeoca will be there, laughing louder than the band."],
  chano_gossip_2: ['chano', "Montesdeoca wants to build a hotel in Artenara. 'Guanche-themed'. Caves with minibars. For that he needs the old site to be worth nothing. Funny, no?"],
  chano_gossip_3: ['chano', "Pepe Santana. Drowned in his bed. His wife says the floor was dry. In La Isleta they're saying the sea is taking back what it's owed."],
  chano_gossip_4: ['chano', "The surfers say the waves come in backwards. Surfers say a lot of things. This one, I believe."],
  chano_gossip_5: ['chano', "Agustín, the old lifeguard. In his armchair, drowned. Somebody saved him in fifty-eight. Now look."],
  chano_gossip_6: ['chano', "Last night La Isleta had the sea in its streets. No rain. No wind. Tonight is San Juan. We'll all go down and walk into the water at midnight. [pause] Maybe not this year."],
  alan_ask_weather: ['alan', "And the forecast?"],
  chano_weather_1: ['chano', "Panza de burro. Grey, warm, all week. Go up the mountain if you want sun."],
  chano_weather_2: ['chano', "Grey. A little mist at dusk. Normal. [pause] Not normal."],
  chano_weather_3: ['chano', "Grey. The mist again, lower. My knees say rain. My knees are liars."],
  chano_weather_4: ['chano', "The solstice. Longest day, grey all of it. And that black fog at dusk. My radio fizzes when it comes."],
  chano_weather_5: ['chano', "Don't go near the water tonight. That's not a forecast. That's my grandmother."],
  chano_weather_6: ['chano', "Bonfires at midnight. And something else. I don't know what. I've never not known."],
  alan_bye_chano: ['alan', "Thanks, Chano."],
  chano_bye: ['chano', "Go with God, and with coins."],
  alan_look_phonebox: ['alan', "A phone box with a view of the sea. Coins only. Every call to Lisbon costs a hundred pesetas and some dignity."],
  alan_phone_nocoins: ['alan', "No coins. Chano at the kiosk will have change. Chano has everything."],
  alan_phone_note: ['alan', "It doesn't take five-thousand-peseta notes. Nobody does. I need change from the kiosk."],
  alan_phone_no_time: ['alan', "No time for phone calls. Not today."],
  ines_hello: ['ines', "Livraria Sanches. [pause] Oh, it's you. Pessoa, it's him. He's ignoring you, in case you were wondering."],
  ines_t_eca_1: ['ines', "Pessoa has been sick on the Eça de Queirós."],
  alan_t_call_1: ['alan', "Hello, Inês."],
  ines_t_eca_2: ['ines', "On the first edition. The one in the window."],
  alan_t_call_2: ['alan', "Is he all right?"],
  ines_t_eca_3: ['ines', "He's fine. He's asleep on the Saramago. The Eça is not fine. [pause] How is it? How's the sun? How's the boyfriend? How is the man who leaves the shop to me for a week, three weeks before I submit my thesis?"],
  alan_t_call_3: ['alan', "You could close the shop."],
  ines_t_eca_4: ['ines', "I could, but then I would have to write my thesis. [pause] Well?"],
  narr_t_surfers: ['narr', "Across the promenade, young surfers were coming in out of the water, their wetsuits peeled to the waist, their hair bleached into stiff gold ropes by the salt, laughing about something."],
  alan_t_call_4: ['alan', "When did surfers get so young?"],
  ines_t_what: ['ines', "What?"],
  alan_t_call_5: ['alan', "Oh. [pause] When I didn't."],
  ines_t_alan: ['ines', "Alan."],
  alan_t_call_6: ['alan', "It's fine. It's lovely. He's lovely. He's happy, Inês. He's been here a week and he's already a different person. He talks about the cave like it's a person. He calls his boss by his first name."],
  ines_t_jealous: ['ines', "[pause] And you're jealous."],
  alan_t_call_7: ['alan', "Of a cave."],
  ines_t_party: ['ines', "Of a cave. [pause] Alan. Go to the party. Be charming. Don't break anything."],
  alan_t_call_8: ['alan', "I'm wearing a stranger's jacket."],
  ines_t_dontknow: ['ines', "I don't want to know."],
  narr_t_money: ['narr', "And the money ran out."],
  alan_ask_ines_now: ['alan', "Inês. What would you do now?"],
  alan_ask_ines_pessoa: ['alan', "How's Pessoa?"],
  ines_pessoa_1: ['ines', "He sleeps on your pillow and looks at me like I've killed you. I'm considering it."],
  ines_pessoa_2: ['ines', "He ate a sardine off the counter while a customer was paying. The customer applauded."],
  ines_pessoa_3: ['ines', "He's sulking in the window. People take photos. We've sold four books to people who came in to pet him."],
  ines_pessoa_4: ['ines', "Grieving. Or overfed. It's hard to tell with him. It's hard to tell with you."],
  ines_pessoa_5: ['ines', "He's fine. He's a cat. He'll outlive us both out of spite."],
  alan_ask_ines_thesis: ['alan', "And your thesis?"],
  ines_thesis: ['ines', "Three weeks to submission and I'm reading your grandfather's foundry papers instead. It's called research. It's called avoidance. You'd know."],
  alan_bye_ines: ['alan', "I have to go. The box is eating my coins."],
  ines_bye: ['ines', "Call me. Don't do anything stupid. Or call me first if you're going to."],
  alan_look_sea_1: ['alan', "Grey sea under a grey sky. The Atlantic in its office clothes."],
  alan_look_sea_mist: ['alan', "The mist lies along the waterline like something asleep. The wind's blowing out to sea. It isn't going anywhere."],
  alan_look_sea_2: ['alan', "The tide came in at ten this morning. The tide table on the promenade says three."],
  alan_look_sea_3: ['alan', "A man drowned in his bed last night and the sea looks innocent. That's how you know."],
  alan_look_sea_4: ['alan', "I can hear it whispering in the surf. Not words. The shape of words."],
  alan_look_sea_5: ['alan', "I don't want to look at it. It's looking at me. It knows what I did last night. It doesn't care, which is worse."],
  alan_look_sea_6: ['alan', "The tide's at the top step. The bonfires are on the sand below it."],
  alan_look_sea_7: ['alan', "Flat. Ordinary. Blue, even."],
  alan_look_steps_1: ['alan', "The promenade steps. The tide reaches the first one. Normal, I suppose. I don't do tides."],
  alan_look_steps_2: ['alan', "Second step. A woman in a deckchair had to move. She blamed the Germans."],
  alan_look_steps_3: ['alan', "Third step. The wet line's higher every day. I'm keeping count. I didn't want to."],
  alan_look_steps_4: ['alan', "Fourth step. The ice-cream cart has moved up to the road."],
  alan_look_steps_5: ['alan', "Fifth step. Nobody's swimming. Nobody's saying why."],
  alan_look_steps_6: ['alan', "The top step. One more and it's in the street."],
  alan_look_bonfire_1: ['alan', "A pile of pallets on the sand."],
  alan_look_bonfire_2: ['alan', "Bonfires for San Juan, on Sunday night. Two of them. Children dragging old furniture down the beach."],
  alan_look_bonfire_3: ['alan', "Five bonfires now, taller than a man. The city's building fires to welcome the shortest night."],
  alan_look_bonfire_4: ['alan', "Taller than the lifeguard tower. Somebody's put a whole wardrobe on that one."],
  alan_look_bonfire_5: ['alan', "They're still building. They don't know what they're welcoming."],
  alan_look_bonfire_6: ['alan', "Tonight they burn. And tonight the door opens. Unless."],
  alan_surf_1: ['alan', "When did surfers get so young? [pause] Oh. When I didn't."],
  alan_surf_2: ['alan', "I could do that. [pause] I could absolutely not do that."],
  alan_surf_3: ['alan', "Looking is free. Looking is also, apparently, all I do now."],
  alan_surf_4: ['alan', "Vasco would say they're fine examples of the human form. Vasco would be right."],
  alan_surf_again: ['alan', "I've looked. I'm done looking. For today."],
  narr_surf_after: ['narr', "He doesn't look at them."],
  surfer_bark_1: ['surfer', "No wind and the swell's up, man. Doesn't make sense."],
  surfer_bark_2: ['surfer', "The waves are coming in backwards, man. Swear to God."],
  surfer_bark_3: ['surfer', "Nobody's going out at dusk. That fog. Smells like a fish market in hell."],
  surfer_bark_4: ['surfer', "Solstice session! [pause] Nah. Look at it. Nah."],
  surfer_bark_5: ['surfer', "My cousin in La Isleta says the sea's giving stuff back. Old stuff. Cannonballs."],
  surfer_bark_6: ['surfer', "We're going up to Pico de las Nieves tonight. Above the cloud. Something's wrong down here."],
  alan_look_tomap: ['alan', "The city. Or as much of it as fits in a taxi."],
  narr_mist_1: ['narr', "And then, out on the water, past the reef, Alan saw the mist. A low black line, like a second horizon. Not the high grey of the panza. Black, oily black, hugging the sea like smoke from a burning ship."],
  narr_mist_2: ['narr', "It was coming in against the wind. He could feel the wind on his face, blowing off the land and out to sea. And the black mist rolled in against it, slowly, deliberately, the way a tide comes in."],
  narr_mist_3: ['narr', "It reached the reef, and the waves breaking on the reef went quiet, all at once, as if someone had laid a hand over them. It reached the sand. And then the smell reached him."],
  narr_t_walk_1: ['narr', "It was after nine, and Vasco was still talking. About Baute, who had found the hidden channel when he was thirty. About the dinner on Thursday. About the light. Alan let him. It was like standing next to a fire."],
  alan_t_walk_1: ['alan', "Let's walk. I want to see the beach."],
  narr_t_walk_2: ['narr', "Further down the sand, men were building something out of wooden pallets and old furniture and dried palm fronds: a great untidy pyramid, taller than a man."],
  vasco_t_sanjuan_1: ['vasco', "For San Juan. Sunday night. They light bonfires all along the beach and the whole city comes down to the sea. You jump over the fires for luck, and at midnight you go into the water."],
  vasco_t_sanjuan_2: ['vasco', "Rayco says the beach looks like it's burning from end to end."],
  alan_t_walk_2: ['alan', "Rayco says."],
  vasco_t_walk_alan: ['vasco', "Alan."],
  alan_t_walk_3: ['alan', "I'm teasing. [pause] Will we be here for it?"],
  vasco_t_sanjuan_3: ['vasco', "I'll be on the mountain. The sunrise on the twenty-fourth is the whole point. It's the morning the light turns back. [pause] But you could come up. You could see it with me."],
  alan_t_walk_4: ['alan', "I could."],
  narr_t_walk_3: ['narr', "He squeezed Vasco's hand, and didn't say yes. They walked to the end of the promenade and stood at the rail. The air was so warm and so heavy it was like breathing through a damp cloth."],
  alan_mist_2: ['alan', "Salt. Cold stone. Rust. [pause] Old, deep water that's never seen the sun."],
  narr_mist_4: ['narr', "He had smelled it once before, eight months ago, at the bottom of a cistern under Lisbon, up to his chest in black water. Something there had looked at him, and known him for the blood of the men who made the bells, and withdrawn."],
  vasco_t_mist_1: ['vasco', "Alan? [pause] What is it?"],
  narr_mist_5: ['narr', "He thought about Vasco's face in the museum, lit up. About the week Vasco was having, the best week of his life, perhaps. About how the light would go out of that face if he said it."],
  alan_mist_3: ['alan', "Nothing. I'm tired. And I think I'm sunburnt in places I didn't know I had."],
  narr_mist_6: ['narr', "Vasco smiled, and put his arm around Alan's shoulders, and turned him gently away from the sea. Behind them, the mist lay along the waterline like something sleeping, and did not move again."],
  vasco_t_walk_up: ['vasco', "I'm going up. Shower. [pause] Don't be long."],
  narr_love_1: ['narr', "It was easy. That was the thing about it. It was easy, and it was funny, and it was familiar, and familiar had always been the word that frightened him most."],
  narr_love_1b: ['narr', "Halfway through, the lift down the corridor sneezed, very loudly, and they both lost it completely, and lay there shaking with laughter with their foreheads pressed together. And then stopped laughing, and didn't need to say anything."],
  narr_love_1_discreet: ['narr', "Alan took off the terrible jacket. [pause] Later, down the corridor, the lift sneezed, very loudly, and they both lost it completely."],
  narr_t_end_1: ['narr', "Afterwards, Vasco fell asleep almost at once, one arm thrown across Alan's chest like a claim. Alan lay awake, listening to the sea through the open balcony doors, and listening for the other sound, the one under the waves."],
  narr_t_end_2: ['narr', "Eight months. A bed by the sea. A man who loved him, asleep with an arm across his chest, as if he might otherwise float away. [pause] This was everything he had ever been afraid of."],
  narr_t_end_3: ['narr', "Outside, on the dark beach, the bonfire stood unlit, waiting for Sunday."],
  vasco_t_night_1: ['vasco', "You've been on the phone to Inês."],
  narr_t_room_1: ['narr', "Vasco was lying on the bed in a towel, reading his notebook and frowning at it, with his glasses on the end of his nose. The ceiling fan turned slowly overhead, stirring the warm air and doing nothing about it."],
  alan_t_night_1: ['alan', "How do you know?"],
  vasco_t_night_2: ['vasco', "You've got your Inês face. Guilty, and a bit pleased with yourself. [pause] What did she say?"],
  alan_t_night_2: ['alan', "Pessoa was sick on the Eça de Queirós."],
  vasco_t_night_3: ['vasco', "The first edition?"],
  alan_t_night_3: ['alan', "The first edition."],
  vasco_t_night_4: ['vasco', "[pause] He always did hate Eça."],
  narr_t_laugh: ['narr', "Alan laughed. It came out of him too suddenly, too loud, like something escaping, and Vasco smiled, and held out his hand."],
  vasco_t_night_5: ['vasco', "Take off that terrible jacket. And come here."],
  // the reception
  alan_look_baute: ['alan', "Tall, thin and very still. A sponsor's suit and a digger's hands. When he looks at you, you feel looked at."],
  baute_t_1: ['baute', "You're Alan. Vasco has told me nothing about you, which is how I know he's in love. [pause] Rayco Baute."],
  baute_t_skulls: ['baute', "They're not frightening. People think they're frightening. They're not. [pause] They're just waiting for us to pay attention."],
  narr_t_baute_1: ['narr', "He had a long, deeply tanned face, silver hair swept back, and a short grey beard. At his throat, on a leather thong, hung a small seal of red clay, carved with triangles."],
  alan_t_baute_1: ['alan', "He's told me a great deal about you."],
  baute_t_2: ['baute', "Then I'm in trouble. I've stolen him from you, I'm afraid. For the week. I'll give him back on Monday."],
  baute_t_2b: ['baute', "He's the best reader of sacred light I've ever worked with, and I've worked with the best. He sees things the rest of us walk past."],
  alan_t_baute_2: ['alan', "He does."],
  narr_t_baute_2: ['narr', "Alan found that he meant it, and that it hurt."],
  baute_t_gran_1: ['baute', "When I was a boy, my grandmother used to take me up to the burial caves above her village. She'd tell me their names. Not the real ones. Nobody remembers the real ones."],
  baute_t_gran_2: ['baute', "She gave them names, so they'd have names. 'This is Tamara. This is Guayasén. Say good morning.'"],
  narr_t_pendant: ['narr', "He touched the clay pendant at his throat, lightly, with two fingers."],
  baute_t_3: ['baute', "There's a hotel there now. With a swimming pool. [pause] You'd like it. Everybody likes it."],
  narr_t_baute_3: ['narr', "Alan was left with a glass of warm white wine and the feeling of having been told something important in a language he didn't speak."],
  alan_ask_baute_cave: ['alan', "What exactly is it, your cave?"],
  baute_t_cave: ['baute', "Cave 6. A dome cut into the rock by people who had no metal. A channel in the roof. At the equinoxes and all through the summer, the sun comes through and moves across engravings on the wall. A calendar, the papers say."],
  baute_t_cave_2: ['baute', "I say it's a prayer. Vasco is going to prove which."],
  alan_ask_baute_vasco: ['alan', "Why him? There must be people on the island."],
  baute_t_vasco: ['baute', "There was. Dr. Suárez. She died in December, on the road down. A terrible thing. [pause] And Vasco reads light the way you read a page."],
  alan_ask_baute_discs: ['alan', "I heard there are mirrors. Obsidian."],
  baute_t_discs: ['baute', "Seven discs in the channel. We're taking them out to conserve them, one at a time. Nine hundred years is long enough in the weather."],
  alan_bye_baute: ['alan', "I'll leave you to your sponsors."],
  baute_t_bye: ['baute', "They're not mine, Mr. Sanches. I'm theirs. That's the arrangement."],
  alan_look_vasco_reception: ['alan', "Vasco, surrounded, drawing the path of the light in the air with both hands. They're really listening to him. [pause] He isn't lost here."],
  vasco_t_reception: ['vasco', "Later. I'm being impressive. [pause] You look nice. Whose jacket is that?"],
  alan_look_carmen_steps: ['alan', "A woman on the steps outside, smoking. Or trying to. Her lighter doesn't want to work. With her back to the party. My kind of person."],
  carmen_t_1: ['carmen', "No."],
  alan_t_carmen_1: ['alan', "Can I have one of those?"],
  carmen_t_2: ['carmen', "You're the boyfriend."],
  alan_t_carmen_3: ['alan', "I'm the boyfriend."],
  alan_t_carmen_2: ['alan', "Fair enough."],
  carmen_t_3: ['carmen', "The bookseller."],
  alan_t_carmen_4: ['alan', "Alan."],
  carmen_t_4: ['carmen', "Carmen Trujillo. I run the archive. [pause] I don't do parties."],
  alan_t_carmen_5: ['alan', "You're at a party."],
  carmen_t_5: ['carmen', "I'm outside a party. There's a difference. [pause] You should know. You're outside it too."],
  carmen_t_6: ['carmen', "Your doctor's very good. Everybody says so. Rayco's in love with him. [pause] Not like that. Rayco's in love with anyone who sees what he sees."],
  alan_t_carmen_6: ['alan', "And what does he see?"],
  carmen_t_7: ['carmen', "Ask him. [pause] Welcome to Gran Canaria. Don't swim after dark."],
  alan_t_carmen_7: ['alan', "Why does everybody keep saying that?"],
  carmen_t_again: ['carmen', "Go back in, bookseller. Your doctor's being brilliant without you."],
  narr_t_carmen_1: ['narr', "There was a woman sitting on the museum steps. She was on her third attempt to light a cigarette with a lighter that didn't want to work. On the third attempt, it did."],
  narr_t_carmen_2: ['narr', "She looked at him. She looked at the jacket. She lowered the sunglasses from the top of her head and looked at him over them, the way a customs officer looks at a suitcase."],
  narr_t_carmen_3: ['narr', "They sat in silence for a while. From inside came the string quartet, and Vasco's voice, rising with enthusiasm, and a burst of laughter."],
  narr_t_carmen_4: ['narr', "Alan said nothing. Carmen held out the packet: Coronas, the local brand, crushed almost flat. She lit one for him, and it took her three tries."],
  narr_t_carmen_5: ['narr', "Carmen looked at him for a long moment. Something moved behind her eyes, something tired and guarded, and then it was gone."],
  alan_look_steps_door: ['alan', "The door to the courtyard steps. Cigarette smoke drifts in. The only honest thing at this party."],
  alan_look_montesdeoca: ['alan', "A heavy man in a white guayabera, with a gold watch and a cigar he isn't allowed to light, nodding along as if he understood every word."],
  montesdeoca_t_1: ['montesdeoca', "Ignacio Montesdeoca. I pay for all this. [pause] Nice jacket. I had one exactly like it. I left it somewhere."],
  alan_t_monte_1: ['alan', "They're very popular this year."],
  montesdeoca_t_2: ['montesdeoca', "Ha! Enjoy it. Enjoy everything. Life is short and the island is beautiful, and I own two of the beaches."],
  montesdeoca_t_again: ['montesdeoca', "Try the gofio. It's like eating the island. Ha!"],
  alan_look_cases: ['alan', "Skulls, shelf after shelf. Mummies in goatskin, curled up like sleepers. The only people in the room I'm not expected to talk to."],
  narr_t_museum_1: ['narr', "El Museo Canario: pale stone and dark wooden balconies around a courtyard in Vegueta. Waiters with warm white wine, a string quartet playing Vivaldi to nobody, and sixty people talking at the tops of their voices."],
  narr_t_museum_2: ['narr', "And all around them, in the old glass cases that lined the walls, the dead. Row after row of skulls, staring out with polite, patient eyes. It was like holding a cocktail party in a crypt."],
  alan_reception_stay: ['alan', "Not yet. Vasco wants me to meet people. Baute. That woman on the steps, who doesn't do parties."],
  alan_look_back: ['alan', "The city's back that way. The man I'm supposed to be is somewhere back there too."],
  alan_look_clerk: ['alan', "The check-in desk. A clerk with a stamp and a printer. Everything about leaving is very easy."],
  alan_look_belt_sun: ['alan', "Nothing on the belt. Nothing coming. That's me. I'm the luggage."],
  alan_look_board_sun: ['alan', "Lisbon. Four o'clock. On time."],
  alan_look_note: ['alan', "A five-thousand-peseta note. Big enough to buy a paper, too big for a phone box."],
  alan_look_coins: ['alan', "Hundred-peseta coins. Each one's a minute of Inês telling me what to do."],
  alan_look_napkin: ['alan', "Me, in biro, on a napkin. Laughing. I look happy. I look like a man who's about to do something stupid."],
  alan_look_water: ['alan', "Two litres of water. For the radiator, and for courage."],
  alan_look_inscription: ['alan', "SANTA ANA ROGA POR NOS. Cast in Lisbon and Las Palmas, 1751. And the mark."],
  alan_look_letter: ['alan', "One word in four. 'Lock'. 'Mountain'. 'Water'. 'Last'. [pause] I don't like any of them."],
  gail_w_1: ['gail', "Did you hear? Derek says a man drowned on the beach. Well, near it. Derek says it's the water. I said, Derek, it's the sea, it's mostly water."],
  gail_w_again: ['gail', "I'm going to sit by the pool. Pools don't do anything funny."],
  derek_w_1: ['derek', "Filmed the sea this morning like you said. Came in backwards. Gail says I had the camera upside down."],
  gail_su_1: ['gail', "We're going down to the beach tonight for the bonfires! They say everyone walks into the sea at midnight. Derek's bought new trunks."],
  derek_su_1: ['derek', "Union Jack. Matching."],
  derek_su_2: ['derek', "Midnight. Into the sea. Forty quid camcorder, waterproof bag. I'm ready."],
  // ---------------------------------------------------------------- Inês's calls, the ones the story needs
  alan_call_tue_1: ['alan', "It's here. [pause] It's come for me."],
  ines_call_tue_1: ['ines', "[pause] What's here?"],
  alan_call_tue_2: ['alan', "You know what."],
  ines_call_tue_2: ['ines', "Alan. [pause] Are you sure?"],
  alan_call_tue_3: ['alan', "I smelled it. I'd know that smell anywhere, Inês. I'll smell it on my deathbed."],
  alan_call_tue_3b: ['alan', "It can't be. We put it back. It's a thousand kilometres from Lisbon."],
  ines_call_tue_3b: ['ines', "It's the same sea, Alan. It's always been the same sea."],
  ines_call_tue_3: ['ines', "Have you told Vasco? [pause] Alan. Have you told Vasco?"],
  alan_call_tue_4: ['alan', "He's happy. He's so happy. It's his week. It's the first thing he's ever had that's just his. I can't walk into the middle of it and say, sorry, darling, I'm being haunted again."],
  ines_call_tue_4: ['ines', "You're not being haunted. You're being sensible. Tell him."],
  alan_call_tue_5: ['alan', "Tomorrow."],
  ines_call_tue_5: ['ines', "Alan."],
  alan_call_tue_6: ['alan', "Tomorrow. I promise. Find out what you can. Anything. Old papers. Anything about the Canaries."],
  ines_call_tue_6: ['ines', "I have a thesis."],
  alan_call_tue_7: ['alan', "Then you'll want something to do instead."],
  alan_call_wed_1: ['alan', "There's a bell in the cathedral here with our mark on it. 1751. And a sealed letter the founders left 'for the next founder who comes'."],
  ines_call_wed_1: ['ines', "Seventeen fifty-one. Four years before. [pause] Fax me everything. The inscription, the letter, your shopping list. I'll be up all night with a dictionary."],
  alan_call_wed_2: ['alan', "Your thesis."],
  ines_call_wed_2: ['ines', "My thesis can wait. It's about the dead. They're patient."],
  ines_call_thu_1: ['ines', "Sit down. Is there somewhere to sit in a phone box? Lean, then. [pause] I found it. In the foundry ledger. 1751: 'Viagem às Canárias, para estudar a fechadura.'"],
  alan_call_thu_1: ['alan', "To study the lock."],
  ines_call_thu_2: ['ines', "And 1755, after the earthquake, in your great-great-whatever's hand: 'Fizemos o que aprendemos nas Canárias. O Mar está calado.' We did what we learned in the Canaries. The Sea is silent."],
  alan_call_thu_2: ['alan', "They learned how to bind it. Here."],
  ines_call_thu_3: ['ines', "There's more. Alan, in the cistern it knew you. It backed away from your blood. Bastos's notes say that's what it hates most: the blood that bound it. [pause] If something's opening a door over there, it won't back away this time. It'll come for you first."],
  alan_call_thu_3: ['alan', "That's a lovely thing to hear in a phone box."],
  ines_call_thu_4: ['ines', "I'm faxing nothing about this to Vasco. You are telling him. Tonight."],
  ines_call_fri_1: ['ines', "You sound terrible. What happened?"],
  alan_call_fri_1: ['alan', "I got caught going through Baute's desk at the dinner. In front of everyone. In front of Vasco. He's gone up the mountain. We had the fight."],
  ines_call_fri_2: ['ines', "The fight. [pause] Did he say the thing? The thing he's been not saying?"],
  alan_call_fri_2: ['alan', "He said a man called Lorenzo."],
  ines_call_fri_3: ['ines', "Oh, Alan. [pause] Go to Carmen. Do something useful with the ache. And don't drink alone tonight."],
  ines_call_sat_1: ['ines', "You're calling at nine in the morning. You never call at nine. [pause] Alan."],
  alan_call_sat_1: ['alan', "I slept with someone. A painter. Twenty-three. I lied to him about Vasco. And I didn't tell Vasco first. I didn't tell anyone first. I didn't tell anyone anything. That's my whole personality."],
  ines_call_sat_2: ['ines', "[pause] It was never the sex. You two said so. It's the rules. Tell first. Never to settle a fight. You broke both."],
  alan_call_sat_2: ['alan', "I know."],
  ines_call_sat_3: ['ines', "Tell him. Today. Not when it's convenient. Not when he's forgiven you for the desk. Today."],
  alan_call_sat_3: ['alan', "The dig radio's off. He's up the mountain."],
  ines_call_sat_4: ['ines', "Then keep trying. [pause] And go to your hotel. The letter: I've decoded it, and I faxed it there an hour ago. Read it sitting down. Alan, I mean it."],

  // ================================================================ WEDNESDAY 19 JUNE: the island
  alan_w_wake: ['alan', "He's gone already. Up the mountain, into the sun. Down here it's grey, and I have a whole day and no idea what to do with it except worry."],
  alan_look_pino: ['alan', "A small woman in black on the quay, sorting the catch with hands like old rope. Her eyes don't miss anything."],
  pino_w_1: ['pino', "You want fish, you come at six. You want to look at old women, you come any time."],
  alan_w_pino_1: ['alan', "I wanted to look at that. In the net. Is that a helmet?"],
  pino_w_2: ['pino', "Castilian. From the conquest. Rusted to lace. My nets brought it up on Monday. Tuesday, a cannonball. Today, the head of a crossbow bolt."],
  alan_w_pino_2: ['alan', "Five hundred years down there, and it comes up now?"],
  pino_w_3: ['pino', "The sea is emptying its pockets, mi niño. My grandmother said it does that before it asks for something back. I'm Pino. Doña Pino, to you."],
  pino_w_again: ['pino', "Go and see the cathedral. Pray, if you know how. I'll keep the helmet. Somebody should."],
  alan_look_lolo: ['alan', "An old man in a flat cap, mending nets, with a cigarette he never lights."],
  lolo_w_1: ['lolo', "Fifty-five years. I married her in a storm. She hasn't forgiven me for the storm."],
  lolo_again: ['lolo', "Mmh."],
  alan_look_nets: ['alan', "Nets drying on the quay. Patched and patched again. Like everything that lasts."],
  alan_look_nets_wed: ['alan', "In the nets, something round and orange with rust. A helmet. A conquistador's helmet, in a fishing net."],
  alan_look_boats: ['alan', "Painted boats. Virgen del Carmen. Virgen del Pino. Half the fleet is named after the Virgin, which seems sensible here."],
  alan_look_finds_2: ['alan', "A rusted helmet, a cannonball and a crossbow bolt, laid out on a sack. 1478, the conquest. The sea is giving it back."],
  alan_look_finds_3: ['alan', "More since yesterday. A sword hilt. A Castilian coin. The sea is clearing its shelves."],
  alan_look_finds_4: ['alan', "A ship's bell, green with age. Nobody's touching it. I'm not going to either."],
  alan_ask_pino_pepe: ['alan', "Pepe Santana. The fisherman. Did you know him?"],
  pino_th_pepe_1: ['pino', "Pepe. [pause] We were on the Virgen del Pino together, in seventy-one. She went down off Gando in a flat calm. Four of us came up. A fishing boat pulled us out."],
  pino_th_pepe_2: ['pino', "I keep the names in my missal. Look."],
  pino_th_debts: ['pino', "The sea had us, and it lost us to other hands. My grandmother said it never forgets a thing taken back from it. Now it's collecting. Pepe first. Then whoever's next."],
  alan_th_debts: ['alan', "And you're on the list."],
  alan_ask_pino_sea: ['alan', "What's happening to the sea, Doña Pino?"],
  pino_th_sea: ['pino', "It's coming in at the wrong hours. It whispers at Las Canteras. And there is a black fog that comes at dusk against the wind, and everyone says, 'It's the panza, Pino, it's June.' [pause] I'm seventy-four. I know June."],
  alan_bye_pino: ['alan', "Look after yourself, Doña Pino."],
  pino_bye: ['pino', "Lolo looks after me. He doesn't sleep. Never has."],
  pino_f_1: ['pino', "Agustín's on the list too. Agustín Ramos, the lifeguard. The sea had him in fifty-eight. I told him to sleep in a chair. [pause] Go home, Portuguese."],
  lolo_f_1: ['lolo', "You've got the face of a man who did something stupid. I've had that face. Fifty-five years, and she still hasn't forgiven me for the first one."],
  alan_f_lolo: ['alan', "And you stayed."],
  lolo_f_2: ['lolo', "Staying's not hard. It's every day. That's all it is. Every day."],
  // Santa Ana
  alan_look_fermin: ['alan', "A small man bent like a question mark in a black cassock-coat, with an enormous ring of keys and glasses as thick as bottle ends."],
  fermin_w_1: ['fermin', "The cathedral is closed for the afternoon, señor. Also for the morning. Also, the clock has stopped. Everything here stops in June."],
  alan_w_fermin_1: ['alan', "You're the sacristan?"],
  fermin_w_2: ['fermin', "Fermín. Fifty years I have kept the bells. The bells are fine. It's me that's stopping."],
  alan_ask_fermin_clock: ['alan', "What's wrong with the clock?"],
  fermin_clock_1: ['fermin', "Nothing. It needs winding. Forty turns of the drum, every Wednesday, since 1888. My hands won't do it any more."],
  fermin_clock_2: ['fermin', "The canon says get a young man. I say young men don't come to cathedrals. [pause] You came."],
  alan_offer_wind: ['alan', "I'll wind it. I have hands. They're mostly decorative, but they work."],
  fermin_ring: ['fermin', "The clock key's on the ring. It has a bell on its bow, like everything here. Which one is it?"],
  fermin_key_wrong_1: ['fermin', "That's the west door. You want to open the cathedral to every tourist in Vegueta? Again."],
  fermin_key_wrong_2: ['fermin', "That one's for the canon's wine. We don't touch that one. Again."],
  fermin_key_right: ['fermin', "That's it. Go up. The drum's on the left of the bell chamber. Mind the third step, it's older than both of us."],
  alan_ask_fermin_bells: ['alan', "How many bells?"],
  fermin_bells: ['fermin', "Five. The oldest was cast in 1751 by Portuguese founders. Strange men. They came to look at the mountain, not the sea, the old records say."],
  alan_ask_fermin_founders: ['alan', "The founders. What else do the records say?"],
  fermin_founders: ['fermin', "That they stayed a summer, cast one bell, and left a letter. And that one of them went up to Artenara at San Juan and came back white as a candle."],
  alan_bye_fermin: ['alan', "Thank you, Don Fermín."],
  fermin_bye: ['fermin', "Go with God. He's slower than he was too."],
  alan_look_clock_stopped: ['alan', "The cathedral clock. Stopped at a quarter past eleven. Not a meaningful quarter past eleven. Just tired."],
  alan_look_clock_going: ['alan', "Going again. A clock I wound. My grandfather would have something to say about that. He'd say it in a ledger."],
  alan_look_dogs: ['alan', "Bronze dogs. The Canary Islands were named for dogs, not birds. Canis. I learned that from a postcard."],
  alan_look_timple: ['alan', "A parranda on the cathedral steps: a timple, a guitar, a woman singing. Like fado that's been to the beach."],
  alan_look_timple_mist: ['alan', "The timple's playing in a minor key now. They don't know why. Neither do I. I do."],
  alan_look_cathedral_door: ['alan', "Santa Ana. Big, grey, Gothic outside, with a sense of humour inside, I bet."],
  alan_cathedral_locked: ['alan', "Locked. Don Fermín has the keys. All of them, by the look of it."],
  // the bell chamber
  alan_look_drum: ['alan', "The clock's winding drum. A cast-iron wheel with a handle, and a sign: 'Forty turns. Not forty-one.'"],
  alan_look_drum_wound: ['alan', "Forty turns. Not forty-one. I counted. Out loud, like a child."],
  alan_drum_again: ['alan', "Forty-one would be showing off."],
  fermin_founder_hands: ['fermin', "Listen. [pause] Ha. Founder's hands, the old men used to say, for whoever could wind it first time. Come. Look at the north bell. Look at its waist."],
  alan_w_hands: ['alan', "Founder's hands. If only you knew."],
  fermin_bell_show: ['fermin', "There. The founders' mark."],
  alan_look_bell_dark: ['alan', "A great dark shape. I can't see a thing up here. It's all shadow and pigeons."],
  alan_look_bell_mark: ['alan', "On the waist of the bell: an S between two little bells. [pause] Our mark. The Sanches mark. Here. In 1751. Before Lisbon. Before any of it."],
  alan_use_bell: ['alan', "I'm not ringing a bell. Not after last time. Not ever again, ideally."],
  alan_bell_item: ['alan', "I want a copy of the inscription, not a souvenir. Paper and pencil. My notebook."],
  alan_rub_bell: ['alan', "A rubbing of the inscription and the mark. Inês will want to see this. Inês will want to frame this."],
  alan_rub_again: ['alan', "I've got the rubbing. One's enough. More than enough."],
  alan_look_bell_window: ['alan', "The whole of Vegueta: flat roofs, palm trees, the sea. And over everything, the grey lid."],
  fermin_belfry_wind: ['fermin', "The drum, señor. On the left. Forty turns."],
  fermin_belfry_look: ['fermin', "Look at the bell, señor. The north one. Look at its waist."],
  fermin_name: ['fermin', "Sanches, the canon says your name is. Sanches. [pause] Like the mark."],
  alan_w_name: ['alan', "My family. The bell-founders of Lisbon. Or what's left of them, which is me and a cat."],
  fermin_letter_1: ['fermin', "Then this is yours. [pause] It has been in the bell chamber since 1751, in a tin, behind the oldest beam. 'For the next founder who comes,' it says on the outside. No one ever came."],
  fermin_letter_2: ['fermin', "Fifty years I have dusted that tin. I'd like to know what's in it before I die. Don't hurry, but don't take long."],
  alan_w_letter: ['alan', "Sealed with wax. The mark again. Faded ink, old Portuguese. I can read one word in four. Inês can read all of them. Inês needs a fax machine."],
  fermin_belfry_again: ['fermin', "Mind the third step on the way down. And come back and tell me."],
  // the archive
  alan_look_carmen: ['alan', "Carmen Trujillo, in a men's linen shirt the colour of rust, sunglasses on her head and a cigarette she isn't supposed to have down here."],
  carmen_w_1: ['carmen', "The bookseller. [pause] Close the door, you're letting the humidity in."],
  alan_w_carmen_1: ['alan', "There's a mist on the beach at dusk. Black. It moves against the wind. I've seen it before. In Lisbon. Last autumn."],
  carmen_w_2: ['carmen', "It's June, cariño. It's the panza de burro. Every June. Go to the beach. Get a tan. Get a cocktail with an umbrella in it."],
  alan_w_carmen_2: ['alan', "It smells of salt and stone. It took four people in Lisbon. In their beds."],
  carmen_w_3: ['carmen', "[pause] I'm busy. [pause] I said I'm busy."],
  carmen_w_galindo: ['carmen', "Here. Abreu Galindo. Read it, and stop telling me things. It's the oldest history of the island. If your fog is in there, come back. If it isn't, go to the beach."],
  carmen_w_again: ['carmen', "Read the book. I'm busy. I have six months of being busy to catch up on."],
  carmen_inscription: ['carmen', "A Portuguese bell in Santa Ana. Fascinating. I'm still busy."],
  carmen_letter: ['carmen', "Eighteenth-century Portuguese. Not my department. Not my century. Not my problem."],
  alan_look_disclist: ['alan', "A conservation list pinned to the board. 'Cueva 6: discos de obsidiana.' Disc one out in December. Disc two out today. One a day, it says, for conservation."],
  alan_look_disclist_late: ['alan', "The list. They're nearly all out. One a day, like pills. Like nails out of a coffin."],
  alan_look_ashtray_2: ['alan', "Four stubs, all the same brand, all half smoked. Somebody keeps starting and stopping."],
  alan_look_ashtray_3: ['alan', "Fuller. She's not sleeping. That makes two of us."],
  alan_look_ashtray_4: ['alan', "Overflowing. And a lighter with no flint left in it."],
  alan_look_stacks: ['alan', "Shelves to the ceiling. Boxes marked by decade. The island's memory, in cardboard."],
  alan_look_cave_photos: ['alan', "Photographs of a cave: a dome, engraved triangles, a blade of light on the wall. Cave 6."],
  alan_look_cave_photos_2: ['alan', "The triangles. All pointing down. Arrows. Carmen's right. Elena was right."],
  alan_look_galindo: ['alan', "'They bathed in the sea at set times.' Underlined twice in pencil. Someone had an idea about this, once."],
  alan_w_done: ['alan', "A helmet from the conquest, discs out of a cave, our mark on a bell and a letter nobody's read in two hundred and fifty years. [pause] I'm going to need a drink and Vasco, in that order."],
  narr_pepe_1: ['narr', "That night, in La Isleta, José Santana goes to bed at ten, as he has for forty years."],
  narr_pepe_2: ['narr', "In the morning his wife finds the bed soaked through with salt water, and the floor dry."],
  alan_look_montesdeoca_wed: ['alan', "Montesdeoca, supervising men with crates. He shouts at the crates as if they owe him money."],
  montesdeoca_w_1: ['montesdeoca', "The Portuguese! With my jacket, I bet. Ha! Come, look. New cases for the museum. My gift. Glass, steel, the best. Even dead people deserve a nice home."],
  alan_w_monte_1: ['alan', "And Artenara? I heard you want to build there."],
  montesdeoca_w_2: ['montesdeoca', "Who told you? Chano? Ha! Yes. A beautiful hotel, in caves, like the old people. Minibars. Rayco hates it. Rayco hates everything with a minibar."],
  alan_look_van: ['alan', "A van with 'Montesdeoca Hoteles' on the side, loading crates at the museum's back door. In? Out? From here, I can't tell."],
  alan_look_cases_wed: ['alan', "Pintaderas, and the space where Montesdeoca's new cases are going. He's paying for the furniture. Who's paying for the dead?"],
  nieves_message_day: ['nieves', "No message, señor. Dr. Teles left at six. With an apple."],
  nieves_message_fri: ['nieves', "Dr. Teles left this morning. With all his bags, señor. No message."],
  nieves_no_message_sat: ['nieves', "No message from Dr. Teles, señor. [pause] None."],
  alan_ask_message: ['alan', "Any messages for me?"],
  alan_ask_fax: ['alan', "Could you fax something to Lisbon for me?"],
  nieves_fax_how: ['nieves', "Give me what you want sent, señor, and the number. The hotel charges by the page. The hotel charges for everything."],
  alan_fax_inscription: ['alan', "This rubbing, please, to Livraria Sanches, Lisbon. The number's on my card."],
  alan_fax_letter: ['alan', "And this letter. Carefully. It's older than the hotel. Older than the island's tourism, which is saying something."],
  nieves_fax_one: ['nieves', "Sent, señor. Lisbon says thank you, in Portuguese."],
  nieves_fax_both: ['nieves', "Sent. Both. Lisbon sends back one word: 'MARAVILHA'. In capitals."],
  nieves_fax_done: ['nieves', "That's already gone, señor."],

  // ================================================================ THURSDAY 20 JUNE: the break-in
  alan_th_wake: ['alan', "He came in at midnight and left at six. Between those, he slept like a man with a clear conscience. I lay there with mine."],
  alan_read_paper: ['alan', "Bonfires, sponsors, the weather. Nothing about mist. Nothing about the sea. Not yet."],
  alan_read_paper_pepe: ['alan', "José Santana. Drowned in his bed. Floor dry. [pause] Maria Coutinho, in Lisbon, the same. It's the same."],
  alan_read_paper_agustin: ['alan', "The lifeguard. In his armchair. Pulled out of a rip in fifty-eight. [pause] Taken back."],
  carmen_th_1: ['carmen', "[pause] I read the paper. Pepe Santana. [pause] Sit down. Not there, that's 1890. There."],
  alan_th_carmen_1: ['alan', "You know something."],
  carmen_th_harimaguadas: ['carmen', "I know history. Before the Castilians, the island had women who served the holy places. Harimaguadas. They lived apart, they wore white, and they bathed in the sea at set times. It's in your Galindo. Underlined, if you looked."],
  carmen_th_conquest: ['carmen', "In 1478 Juan Rejón landed and built a camp in the Guiniguada ravine. Las Palmas. Five years of war. The islanders fought with stones and wooden spears against steel, and won for longer than anyone had a right to."],
  carmen_th_ansite: ['carmen', "In 1483, at Ansite, the last of them surrendered. Bentejuí and the Faycán of Telde climbed the cliff, shouted 'Atis Tirma!', and jumped. For my land. That's the end in the books."],
  alan_th_carmen_2: ['alan', "And outside the books?"],
  carmen_th_legend: ['carmen', "Rayco tells it in his lectures, as a legend. That spring the Harimaguadas called the sea on the Castilian ships off Gáldar. It came. Black, against the wind. And then it wouldn't stop. They went up to the cave and shut it out, at sunrise, on what the Castilians called Saint John's day."],
  carmen_th_grandmothers: ['carmen', "And in Artenara the grandmothers have a saying: 'la cueva aguanta el mar.' The cave holds the sea down. [pause] I always thought it was poetry."],
  alan_ask_carmen_castilians: ['alan', "Is there anything from the other side? The Castilians?"],
  carmen_th_colon: ['carmen', "Casa de Colón. The library on the first floor. Ask for Mercedes Quintana. She'll look at you over her glasses. Let her. She has a file nobody asks for."],
  alan_ask_carmen_magec: ['alan', "Magec?"],
  carmen_th_magec: ['carmen', "The sun. Above everything. The sea answered to nothing, the old people said, except the sun. It doesn't answer to the sun either. It just goes quiet when the sun's watching."],
  alan_ask_carmen_baute: ['alan', "What's Baute like? Really?"],
  carmen_th_baute: ['carmen', "Rayco taught me everything. He's right about everything this island lost. The burial grounds, the coast, the names. He's been right for thirty years, and he's lost every fight. [pause] That does something to a man."],
  alan_ask_carmen_monte: ['alan', "And Montesdeoca?"],
  carmen_th_monte: ['carmen', "A pig in a guayabera. He wants Artenara for a theme hotel. If someone's pulling discs out of that cave to make it worthless, I'd look at him first. [pause] I'd look at him first for most things."],
  alan_ask_carmen_elena: ['alan', "The list says disc one came out in December. The night before Dr. Suárez died."],
  carmen_th_elena: ['carmen', "[pause] Don't. [pause] Not today."],
  alan_bye_carmen: ['alan', "Thank you, Carmen."],
  carmen_bye: ['carmen', "Don't thank me. Bring cigarettes."],
  alan_look_mercedes: ['alan', "Small, straight-backed, a grey cardigan in thirty-degree heat, a grey bun and half-moon glasses on a chain. A librarian from central casting, and probably armed."],
  mercedes_1: ['mercedes', "Carmen telephoned. She said a Portuguese man would come and ask about the sea, and that I should be kind. I'm rarely kind. Sit."],
  alan_th_mercedes_1: ['alan', "I'll take whatever's going."],
  mercedes_2: ['mercedes', "Quintana. My family has been in this city since there was a city. One of us was a ship's master. He gave testimony. Nobody reads it."],
  alan_ask_inquiry: ['alan', "May I read it?"],
  mercedes_inquiry: ['mercedes', "The royal inquiry of 1484, into the loss of three caravels and the camp before Gáldar. Gloves, please. [pause] There."],
  alan_th_inquiry: ['alan', "Black, against the wind. Every night for three months. Into low places and beds. And on Saint John's morning, it went back."],
  mercedes_women: ['mercedes', "Read the margin. The notary's hand. 'Nadie preguntó a las mujeres.' Nobody asked the women. [pause] In 1505 the Holy Office asked for the file and spent a year looking for 'the witches of eighty-three'. They found no one. Women are good at not being found."],
  mercedes_low: ['mercedes', "And Mr. Sanches. Since you have that look. Stay out of the low places this week. Ground floors. Cellars. Beaches. It's what Juan should have done."],
  alan_ask_mercedes_juan: ['alan', "What happened to Juan de Quintana?"],
  mercedes_juan: ['mercedes', "A Canario fisherman pulled him out of the water off Gáldar. Eleven days after he swore that testimony, they found him drowned. In his bed. [pause] The family has always slept upstairs."],
  alan_ask_mercedes_san_juan: ['alan', "And the bonfires? San Juan?"],
  mercedes_san_juan: ['mercedes', "The bishop called it a miracle of the Baptist. So every year on the night of San Juan, the whole city goes down and walks into the sea at midnight, to give thanks. Nobody remembers for what."],
  alan_bye_mercedes: ['alan', "Thank you, Señora Quintana."],
  mercedes_bye: ['mercedes', "Upstairs, Mr. Sanches. Sleep upstairs."],
  alan_look_parrot: ['alan', "A parrot in the courtyard. It looks at me as if it's heard about me."],
  parrot_squawk: ['parrot', "[squawks] ¡Cristóbal! [squawks] ¡Cristóbal!"],
  alan_look_colon_shelves: ['alan', "Manuscripts about Columbus, who stopped here on the way to discovering that somebody was already there."],
  alan_look_colon_balcony: ['alan', "A carved wooden balcony over a courtyard of palms. Even the shade is old here."],
  narr_dinner: ['narr', "Thursday evening. El Museo Canario's fundraising dinner: tablecloths, candles, sponsors, and the expedition's new specialist, presenting."],
  vasco_th_speech_1: ['vasco', "The channel isn't decoration. It's an instrument. Somebody, nine hundred years ago, aimed the sun."],
  vasco_th_speech_2: ['vasco', "My job this week is to find out at what. [pause] Thank you. I'm told there's dessert."],
  baute_th_toast: ['baute', "To the dead of this island, who are cleverer than all of us. And to the living, who pay for them."],
  alan_th_dinner_1: ['alan', "The discs are vanishing, Montesdeoca wants the site worthless, and his contracts are in Baute's office. Through that corridor. Past that guard. [pause] I'm not going to ask anyone. Asking is for people who can bear the answer."],
  alan_look_vasco_dinner: ['alan', "Vasco, surrounded. Three sponsors and a bishop. He's doing his serious face, the one that makes donors write cheques."],
  vasco_th_dinner: ['vasco', "Not now, Alan. Please. [pause] Later."],
  baute_th_busy: ['baute', "Mr. Sanches. Enjoying the island? Good. Good."],
  montesdeoca_th_1: ['montesdeoca', "Portuguese! You came! Eat. Drink. I'm paying, and I'm watching, ha!"],
  alan_look_guard: ['alan', "The museum guard, in a chair by the corridor to the offices. He's asleep. Asleep with one eye, like a cat."],
  guard_th_1: ['guard', "Offices are closed, señor. Toilets are the other way. Everything you want is the other way."],
  guard_th_stop: ['guard', "Señor. The other way."],
  guard_th_wake: ['guard', "Señor! ¡Señor! You can't film that! That's behind the rope! ¡Señor!"],
  alan_look_corridor: ['alan', "A corridor to the offices, and a guard between me and it."],
  alan_look_corridor_free: ['alan', "The chair's empty. Somewhere, Derek is having the best night of his holiday."],
  gail_th_1: ['gail', "Derek's gone to a dinner at the museum. I'm having the buffet. One of us has to be sensible."],
  gail_th_dinner: ['gail', "Derek's got his camcorder out. I said, Derek, they'll think you're a spy."],
  alan_look_derek_cam: ['alan', "Derek, camcorder up, filming a bowl of olives with total commitment."],
  derek_th_1: ['derek', "Forty quid this thing, and all I've got is olives. I want something exclusive. Something they don't show the tourists."],
  alan_derek_rope: ['alan', "Derek. The best thing in the building is behind that rope down there. The mummies. They never let anyone film them."],
  derek_th_go: ['derek', "Mummies! Gail! Mummies!"],
  gail_th_go: ['gail', "Oh, Derek."],
  alan_th_clear: ['alan', "Corridor's clear. Forgive me, Derek. Forgive me, mummies."],
  alan_derek_vasco: ['alan', "Film the man talking. He's the best thing here."],
  derek_th_vasco: ['derek', "The professor? I've got twenty minutes of him already. Gail says he's dishy. I say he talks a lot."],
  alan_bye_derek: ['alan', "Enjoy the olives."],
  derek_th_bye: ['derek', "Olives. Story of my life."],
  derek_th_busy: ['derek', "Shh! Mummies!"],
  alan_look_table: ['alan', "The dinner table. Silver, linen, a knife at every place. Mine's going to be missing one."],
  alan_take_knife: ['alan', "A dinner knife. Good steel. Montesdeoca's money, probably. Nobody's looking."],
  alan_table_again: ['alan', "One knife's theft. Two is a cutlery problem."],
  alan_dinner_stay: ['alan', "I'm not leaving without what's in that office. I've come this far, alone, like an idiot."],
  alan_look_knife: ['alan', "A dinner knife. Good for butter, cheese and the locks of trusting people."],
  // Baute's office
  alan_look_desk: ['alan', "The desk. One drawer locked. The contracts will be in there. Montesdeoca's name on every page, if there's any justice."],
  alan_look_desk_open: ['alan', "Open. I opened it. I'm a burglar now. I'll put it on my card."],
  alan_desk_locked: ['alan', "Locked. A cheap lock. A thin blade would do it."],
  alan_desk_knife: ['alan', "The knife in the gap, a twist, and the cheap lock gives. I'm good at this. I wish I wasn't."],
  alan_look_contracts: ['alan', "The sponsor contracts, in a pile on the side. Sponsorship, insurance, catering. Montesdeoca's paying for the vol-au-vents. Nothing else."],
  alan_look_baute_window: ['alan', "The window looks toward the sea. It's the only window in the building that does."],
  alan_look_baute_shelves: ['alan', "Excavation reports going back thirty years. Every one of them ends 'objection rejected'."],
  alan_th_desk_1: ['alan', "A bulldozed burial ground, 1966. And a map of the south coast with six hotels circled in red. Four of them are Montesdeoca's."],
  alan_th_desk_2: ['alan', "It's him. Montesdeoca. 'Twenty-third, at dawn.' He's going to do something on San Juan—"],
  alan_th_too_late: ['alan', "Too late for that."],
  baute_caught_1: ['baute', "Mr. Sanches. [pause] Were you looking for the toilets?"],
  alan_caught_1: ['alan', "I. [pause] The discs. Montesdeoca. I thought—"],
  baute_caught_2: ['baute', "No, no. Please. It's quite all right. People look through my desk all the time. Usually they're from the planning office."],
  montesdeoca_caught: ['montesdeoca', "The Portuguese! In my jacket! Ha! [pause] Rayco. Is that my map?"],
  baute_caught_3: ['baute', "Vasco, take your friend home. He's tired. It's the sun. It affects people from the north."],
  narr_caught_vasco: ['narr', "Vasco says nothing at all. He puts down his glass very carefully, as if it might break, and walks out ahead of him."],
  narr_thu_night: ['narr', "The hotel room. Vasco on his side of the bed, facing the wall. Not asleep."],
  alan_thu_night: ['alan', "I'll say sorry in the morning. In the morning I'll know how."],

  // ================================================================ FRIDAY 21 JUNE: the solstice
  vasco_f_1: ['vasco', "Don't. [pause] Don't say sorry yet. I want to say something first, and if you say sorry I'll accept it, and I won't say it, and in a month it'll come out over the washing up."],
  alan_f_1: ['alan', "Okay."],
  vasco_f_2: ['vasco', "You went through his desk. In front of my sponsors. In front of the first people who've ever looked at me as something other than the priests' archaeologist. Why?"],
  alan_f_choice_a: ['alan', "Because something's wrong here, and nobody would listen."],
  alan_f_choice_b: ['alan', "Because I'm an idiot. You knew that when you moved in."],
  alan_f_choice_c: ['alan', "Because I didn't want to ruin your week."],
  vasco_f_3a: ['vasco', "Nobody? You didn't ask me. You didn't ask anyone. You never ask. You'd rather break into a desk than say 'Vasco, I'm frightened'."],
  vasco_f_3b: ['vasco', "Don't do that. Don't make it a joke so I have to laugh. You always do that, and I always laugh, and I'm not laughing."],
  vasco_f_3c: ['vasco', "Well. You've ruined it now. Very thoroughly. [pause] You could have just told me."],
  vasco_f_4: ['vasco', "Eight months. I wake up and you're on the edge of the bed, like a guest. Every time I need something from you, you look for the door."],
  alan_f_4: ['alan', "That's not fair."],
  vasco_f_lorenzo_1: ['vasco', "In Rome, before the Patriarchate, there was a man. Lorenzo. A restorer. Four years. [pause] He wanted to live together, properly, out loud. I was frightened. Of my Church, of my mother, of being seen."],
  vasco_f_lorenzo_2: ['vasco', "So I left. One morning. I left him a note on the pillow. I've been sorry for eleven years."],
  vasco_f_lorenzo_3: ['vasco', "I've been the one who leaves. I know what it looks like from the doorway. [pause] I won't be left by a man who's scared."],
  alan_f_5: ['alan', "I'm not leaving."],
  vasco_f_leave: ['vasco', "No. I am. Up the mountain, with the team, for the solstice. I need two days of light and stone. [pause] I'll radio. Maybe."],
  narr_fight: ['narr', "The door closes quietly. Vasco has never slammed a door in his life."],
  alan_f_alone: ['alan', "The longest day of the year. Wonderful. That's a lot of day."],
  carmen_f_early: ['carmen', "It's morning. I don't talk in the morning. Come back after lunch."],
  carmen_f_1: ['carmen', "The burglar. [pause] You look terrible. Sit. I'm making coffee. That's not kindness, I want one."],
  alan_f_carmen_1: ['alan', "I went through Baute's desk."],
  carmen_f_coffee: ['carmen', "The whole island knows. Montesdeoca's telling it at every bar in Triana. You're famous. [pause] Sugar?"],
  carmen_f_beam: ['carmen', "Look at these. Cave 6. The channel in the roof lets a beam of sun into the cave, and through the summer it crosses the wall at the same places on the same days."],
  carmen_f_triangles: ['carmen', "The triangles on the wall. Fertility symbols, the textbooks say. Look at them. Every one points down. They're arrows."],
  carmen_f_discs: ['carmen', "And the discs in the channel are mirrors. Obsidian. They don't decorate the beam. They steer it. [pause] A friend of mine thought so."],
  alan_f_carmen_2: ['alan', "And San Juan? Why does it all point at San Juan?"],
  carmen_f_san_juan: ['carmen', "The solstice is today. The sun stops for three days, rising in the same place. On the fourth morning it starts back. That's the twenty-fourth. Rome put the summer solstice there, and the Church put Saint John on top of it."],
  carmen_f_friend: ['carmen', "My friend said the lock is weakest the morning the sun turns back. [pause] I don't know why I'm telling you this."],
  alan_f_carmen_3: ['alan', "Because I'm the only one who's said 'black mist' to you out loud."],
  carmen_f_go_home: ['carmen', "[pause] Go home, Alan. Before Sunday. Take the plane. I mean it."],
  alan_ask_carmen_friend: ['alan', "Your friend. Was it Dr. Suárez?"],
  carmen_f_friend_2: ['carmen', "Was. [pause] Drink your coffee."],
  alan_ask_carmen_sunday: ['alan', "What happens on Sunday?"],
  carmen_f_sunday: ['carmen', "San Juan. The bonfires. The whole city in the sea at midnight. And at sunrise, the cave. [pause] I don't know. That's why you should go home."],
  carmen_f_bye: ['carmen', "Go home."],
  // the bar
  narr_bar: ['narr', "Friday night, Vegueta. A bar on Calle Mendizábal with three tables, a domino game and a painter behind the counter."],
  alan_bar_in: ['alan', "One drink. One. Then the hotel, and the phone, and sorry."],
  alan_look_rafa: ['alan', "The barman. Twenty-three, maybe. Curls, stubble, a pencil behind his ear and charcoal on his fingers. He looks like the man I wanted to be at twenty-three, and wasn't."],
  alan_look_rafa_2: ['alan', "He draws while he talks and never looks down. I can't stop looking up."],
  rafa_1: ['rafa', "You look like a man who needs rum. Or a hug. We only do rum."],
  alan_rafa_1: ['alan', "Rum's fine. Rum's a hug in a glass."],
  rafa_2: ['rafa', "Arehucas. Island rum. Seven years old. It's better than me and I'm older."],
  alan_rafa_rum: ['alan', "That's dangerous. That tastes like a good decision."],
  rafa_3: ['rafa', "Rafa. I paint. I serve drinks so I can paint. You?"],
  alan_rafa_2: ['alan', "Alan. I sell books. I came here on holiday and I'm ruining it. Professionally."],
  rafa_4: ['rafa', "Everybody ruins their holiday. That's what they're for."],
  alan_ask_rafa_paint: ['alan', "What do you paint?"],
  rafa_paint: ['rafa', "People. Hands, mostly. Hands don't lie. Faces lie all the time."],
  alan_rafa_paint: ['alan', "What do mine say?"],
  alan_ask_rafa_draw: ['alan', "Would you draw me?"],
  rafa_draw_1: ['rafa', "I already am. Look at the counter. No, look at me."],
  yeray_bar_1: ['yeray', "...it's not conservation, he says conservation, but it's not, I carry them..."],
  rafa_draw_2: ['rafa', "Hold still. You're laughing. Stop laughing. No, keep laughing."],
  rafa_draw_3: ['rafa', "There. On a napkin. Museum quality."],
  alan_rafa_napkin: ['alan', "I look happy. When did that happen?"],
  yeray_bar_2: ['yeray', "...down to the lower vault, at night, only Rayco has the key, and the doctor doesn't know..."],
  alan_rafa_napkin_2: ['alan', "Sorry, what? [pause] Never mind. Another, please."],
  alan_ask_rafa_island: ['alan', "Do you ever leave? The island?"],
  rafa_island: ['rafa', "Why would I? The sea's here, the light's here. Everyone comes to me. You came to me."],
  yeray_bar_3: ['yeray', "...should I tell the doctor, the Portuguese doctor, he's good, he'd know what to do..."],
  alan_rafa_island: ['alan', "I did, didn't I."],
  alan_ask_rafa_another: ['alan', "Another one."],
  rafa_another: ['rafa', "To ruined holidays."],
  alan_bye_rafa: ['alan', "I should go."],
  rafa_bye: ['rafa', "Should is a big word for this time of night."],
  rafa_napkin_back: ['rafa', "Keep it. I'll draw you another one. A better one."],
  alan_look_yeray_bar: ['alan', "A boy at the far end of the bar, dusty boots, talking to his glass. Nobody's listening. I'm not either."],
  alan_yeray_1: ['alan', "You all right there?"],
  yeray_bar_4: ['yeray', "My professor... he's a great man. A great man. He carries them down every night, the discs, to the vault under the caves, and he says it's conservation..."],
  yeray_bar_5: ['yeray', "...and the doctor from Lisbon doesn't know, and I should tell him, and I'm going to tell him, tomorrow, I'm going to..."],
  alan_yeray_2: ['alan', "Sounds rough. [pause] Rafa, are you doing that thing with the pencil again?"],
  alan_look_bottles: ['alan', "Rum, rum, rum, and a bottle of something green that nobody's touched since Franco."],
  alan_look_domino: ['alan', "Four old men slapping dominoes down like they're settling a war. They don't look up. They've seen men like me before."],
  alan_stay_0: ['alan', "I came in for one drink. I haven't had it yet."],
  alan_stay_1: ['alan', "One more."],
  alan_stay_2: ['alan', "He's not even answering his radio."],
  alan_stay_3: ['alan', "I'm just talking."],
  rafa_closing: ['rafa', "I'm closing. [pause] I live upstairs. The view is terrible. The coffee is worse."],
  rafa_someone: ['rafa', "Is there someone?"],
  alan_someone_no: ['alan', "No."],
  alan_someone_no2: ['alan', "[pause] No."],
  rafa_after_lie: ['rafa', "Good. [pause] Come on, then."],
  narr_rafa_night: ['narr', "He goes up the stairs. Both answers were lies. He knew it on the first step."],

  // ================================================================ SATURDAY 22 JUNE: the morning after
  alan_s_wake_1: ['alan', "Sun through a window I don't know. Turpentine. A pillow that smells of someone else's shampoo."],
  alan_s_wake_2: ['alan', "[pause] Oh, no. [pause] Oh, Alan."],
  alan_look_rafa_morning: ['alan', "Rafa, at the stove in his shorts, making coffee and humming. He's happy. One of us should be."],
  alan_look_rafa_bed: ['alan', "I can't look at it."],
  alan_look_studio_window: ['alan', "Vegueta's roofs, in sunshine. Up here, on a Saturday, the panza's broken. Of course it has."],
  alan_studio_stay: ['alan', "Not like that. Not without saying it. I've done enough leaving without saying it to last me."],
  alan_look_drawing: ['alan', "Me. Asleep. In charcoal. He drew me while I slept. [pause] I look about twenty-five and completely at peace. I'm neither."],
  alan_read_sketchbook_1: ['alan', "The boy at the end of the bar. Yeray, from the dig. And his words, written down while I wasn't listening."],
  alan_read_sketchbook_2: ['alan', "'The discs go down to the lower vault at night. Only Rayco has the key.' [pause] Not Montesdeoca. Baute. It was Baute all along, and the clue was a metre from my elbow while I was busy lying."],
  alan_read_sketchbook_3: ['alan', "And me. 'El portugués. Triste.' [pause] He's a good artist."],
  rafa_s_1: ['rafa', "You snore. Not much. Like a cat. Coffee?"],
  alan_s_rafa_1: ['alan', "Rafa. I need to tell you something."],
  rafa_s_2: ['rafa', "Uh-oh. The face. [pause] Go on."],
  alan_s_truth: ['alan', "When you asked if there was someone. There is. He's on a mountain. We had a fight. I came here so I didn't have to think about it."],
  alan_s_truth_2: ['alan', "It's not the sex. We're allowed. It's that I lied to you, and I'll have to tell him, and I didn't tell him first. I lied to two people in one night. That's a record, even for me."],
  rafa_s_truth_1: ['rafa', "[pause] Okay. [pause] Okay. I'm a big boy. You should have said."],
  rafa_s_truth_2: ['rafa', "You'd better tell him, then. Before he hears it from Yeray. Yeray tells everybody everything."],
  alan_s_truth_3: ['alan', "I'm sorry."],
  rafa_s_drawing: ['rafa', "Take the drawing anyway. [pause] Take it. It's the last time you'll look that young."],
  alan_s_thanks: ['alan', "Thank you. [pause] For the coffee. For the honesty. Mostly for the coffee."],
  rafa_s_bye: ['rafa', "Go on. Go and be an idiot somewhere else. Good luck with your someone."],
  rafa_s_again: ['rafa', "Go. Tell him."],
  alan_s_coffee: ['alan', "Is there sugar?"],
  rafa_s_coffee: ['rafa', "No. There's honesty. Have some of that."],
  rafa_napkin_keep: ['rafa', "Keep that too. Frame it. Or burn it. Up to you."],
  nieves_sat_eyebrow: ['nieves', "Good morning, señor Sanches. [pause] Last night's shirt is very nice."],
  alan_sat_nieves: ['alan', "Thank you, Nieves. It's had a big night."],
  alan_ask_fax_in: ['alan', "Has a fax come for me? From Lisbon?"],
  nieves_fax_in: ['nieves', "Four pages, señor, an hour ago. The machine nearly gave up."],
  alan_read_fax_1: ['alan', "'The Sea strikes first at whoever understands the lock. It comes for every soul that was taken back from it.' [pause] Pepe. Agustín. Doña Pino. And Elena. She understood it."],
  alan_read_fax_2: ['alan', "'The last of the women set the stones with her own hands, standing in the water. When the door shut, she went down with it.' [pause] Whoever closes it doesn't come back."],
  alan_look_fax: ['alan', "The letter, decoded. In Inês's handwriting, which is worse than the eighteenth century's."],
  alan_s_after_fax: ['alan', "And Vasco is on the mountain reading the lock. He's the best in the world at understanding things. [pause] I have to reach him."],
  alan_dig_no_answer: ['alan', "The dig camp. It rings and rings. Nobody. The radio's off, or somebody's turned it off."],
  ines_hint_vasco: ['ines', "You've told me. Now you have to tell him. Go to the mountain, Alan."],
  narr_flood_1: ['narr', "Saturday evening. The black mist rolls into La Isleta against the wind, and behind it, the sea, up the streets, into the low doorways. No rain. No wind."],
  lolo_s_1: ['lolo', "Pino! Pino! ¡Despierta!"],
  pino_s_1: ['pino', "[pause] Salt. In my mouth. Lolo. In my bed."],
  lolo_s_2: ['lolo', "I was mending the nets. I'm always mending the nets. Fifty-five years, I don't sleep. Now you know why."],
  pino_s_list: ['pino', "It came for me, Portuguese. Lolo was awake. [pause] Look at my list."],
  alan_s_list: ['alan', "Two names crossed out. Hers not, thanks to a man who doesn't sleep."],
  alan_s_name: ['alan', "Give me your pen, Doña Pino. [pause] Not for the same reason. But it's coming."],
  pino_s_name: ['pino', "Then you'd better find someone who doesn't sleep."],
  alan_s_vasco: ['alan', "Vasco read the lock. He's the best in the world at it. Which means it's coming for him too."],
  alan_s_night: ['alan', "The radio's dead. The roads are dark. I'm in a hotel room with a plane ticket. [pause] Tomorrow."],
  narr_cut_alan: ['narr', "Las Palmas. Alan, on the hotel bed, staring at the phone."],

  // ================================================================ SATURDAY: Vasco's chapter
  vasco_v_wake: ['vasco', "I haven't slept. Two days of light and stone, I said. [pause] Stone, then."],
  vasco_look_cloud: ['vasco', "Alan would make a joke about this. Something about heaven, and being overdressed for it. [pause] I'm not thinking about Alan."],
  vasco_look_radio: ['vasco', "Off. [pause] Good. I don't want to talk to him either."],
  vasco_look_finds: ['vasco', "The expedition files. Elena Suárez's drawings: sun-path charts of Cave 6 by date and hour. [pause] Suárez. My predecessor. Good hand. Better than mine."],
  vasco_take_charts: ['vasco', "Her charts, my chalk, the clinometer and my notebook. A day's work."],
  vasco_finds_again: ['vasco', "I have what I need. More than I wanted."],
  vasco_need_charts: ['vasco', "Not without Elena's charts. I'd only be guessing, and the cave deserves better."],
  vasco_look_notebook: ['vasco', "Twelve pages of measurements and one sentence I've crossed out four times."],
  vasco_look_notebook_2: ['vasco', "It says 'I'm sorry'. It's not for the cave."],
  vasco_look_yeray: ['vasco', "Yeray, hungover, making coffee on a camping stove. He's twenty-four and looks like he's carried something heavy all night."],
  yeray_v_01: ['yeray', "Morning, doctor. Coffee? It's terrible."],
  vasco_v_01: ['vasco', "Then yes."],
  yeray_v_02: ['yeray', "I was in Vegueta last night. Rafa's bar. [pause] There was a Portuguese guy there. Funny. Sad, though."],
  vasco_v_02: ['vasco', "Most Portuguese men are. It's the national sport."],
  yeray_v_03: ['yeray', "[pause] Doctor. The discs. Dr. Baute says they're going down to Las Palmas, for conservation."],
  vasco_v_03: ['vasco', "Yes."],
  yeray_v_04: ['yeray', "They're not going to Las Palmas. [pause] Forget it. I'm hungover."],
  yeray_v_05: ['yeray', "Ask Dr. Baute. Please. Not me."],
  vasco_look_chalk: ['vasco', "Chalk. The archaeologist's confession: I was here, I thought this mattered."],
  vasco_look_clinometer: ['vasco', "A clinometer. It measures angles. The only instrument I own that never lies to me."],
  vasco_look_charts: ['vasco', "'Con los siete.' With all seven. Her line runs to the great triangle at San Juan sunrise. She knew."],
  vasco_look_trowel: ['vasco', "Lorenzo gave me this in Rome. 'For the day you find something worth keeping.' [pause] I thought I had."],
  vasco_look_torch: ['vasco', "A pocket torch with a dying battery. Use it like a prayer: briefly, and only when it matters."],
  vasco_look_triangles: ['vasco', "Fertility symbols, the textbooks say. [pause] They're arrows. Every one of them points down."],
  alan_look_triangles: ['alan', "Arrows. All pointing down. Into the floor. At the door."],
  vasco_look_sockets: ['vasco', "Fresh tool marks. Steel, not stone. Someone's been prying these out with a modern chisel. Five empty. Two still holding."],
  vasco_look_disc: ['vasco', "Obsidian, polished to a mirror. I can see myself in it. I look like a man who hasn't slept."],
  vasco_disc_item: ['vasco', "No. Measure it, don't decorate it."],
  vasco_look_beam: ['vasco', "My whole career has been churches built so the light lands on the altar on the right morning. The priestesses did it first. And better."],
  vasco_look_salt: ['vasco', "A white crust low on the wall. [pause] Salt. A thousand metres above the sea. That isn't possible."],
  vasco_look_rock: ['vasco', "A flat rock by the mouth, worn smooth by nine hundred years of people sitting on it and waiting for the sun."],
  vasco_wait: ['vasco', "Half an hour. The beam has moved along the wall."],
  vasco_wait_last: ['vasco', "Eleven. The beam's nearly done with the wall for today."],
  vasco_need_chalk: ['vasco', "I need something to mark it with."],
  vasco_mark_1: ['vasco', "One. Nine o'clock. Now wait, and mark it again."],
  vasco_mark_2: ['vasco', "Two. It's moving faster than I'd think. Once more."],
  vasco_mark_3: ['vasco', "Three. Now. Elena's charts against my marks."],
  vasco_marked_already: ['vasco', "I've marked it here. Wait for it to move."],
  vasco_marks_enough: ['vasco', "Three marks. Enough. Compare them with Elena's charts."],
  vasco_look_marks: ['vasco', "My chalk circles, where the beam fell."],
  vasco_look_marks_3: ['vasco', "Three circles. Elena's charts would tell me where they should have been."],
  vasco_compare_early: ['vasco', "One mark is a point. Three is a path. I need three."],
  vasco_offpath_1: ['vasco', "Her path runs over the triangles. Mine runs over bare rock. [pause] It's off. The beam's off its path."],
  vasco_offpath_2: ['vasco', "Five discs out, and the light is going where nobody meant it to go."],
  vasco_disc_why: ['vasco', "Not yet. First I need to know what it's doing, not what I want it to do."],
  vasco_steer_1: ['vasco', "It turns. [pause] And the beam bends, and lands, there, on a triangle."],
  vasco_steer_2: ['vasco', "They're not decoration. They steer the light. Every disc is a hand on the wheel."],
  vasco_disc_again: ['vasco', "Leave it where it is. It's doing what it was made for."],
  vasco_look_great: ['vasco', "The great triangle at the back of the cave. The biggest arrow of all, pointing at the floor."],
  alan_look_great: ['alan', "The great triangle. Point down. At the floor. At the door."],
  vasco_sanjuan_early: ['vasco', "I don't know yet what the discs do. I'd be drawing fairy tales."],
  vasco_sanjuan_1: ['vasco', "All seven discs in. San Juan. Sunrise. The sun four days off the solstice, starting back. [pause] The beam goes..."],
  vasco_sanjuan_2: ['vasco', "Dead centre. On the great triangle. That's the lock. And the last disc in the line decides whether it falls true."],
  vasco_sanjuan_again: ['vasco', "Dead centre. I've checked it twice."],
  vasco_measure_early: ['vasco', "Measure what? I don't know yet where it has to point."],
  vasco_measure_again: ['vasco', "Twenty-three degrees, twenty-six minutes. I won't forget it."],
  vasco_v_04: ['vasco', "Twenty-three degrees, twenty-six minutes. [pause] The tilt of the world. Of course it is."],
  vasco_v_05: ['vasco', "It isn't counting days. It's holding something down."],
  vasco_v_06: ['vasco', "Every disc is a nail. [pause] And someone's pulling the nails out."],
  vasco_v_radio: ['vasco', "I have to call. [pause] Alan. [pause] I'm not speaking to Alan. I'll call anyway."],
  vasco_radio_fuse: ['vasco', "The fuse is gone. [pause] Radios don't lose their fuses by themselves."],
  vasco_radio_fuse_2: ['vasco', "No fuse. No radio. No one."],
  vasco_look_baute: ['vasco', "Rayco, in his shirtsleeves and his field hat, with a thermos. The way he's stood at the mouth of every cave I've seen him in. As if he owns the view."],
  baute_v_01: ['baute', "You've solved it. I knew you would. [pause] Coffee? Mine's better than Yeray's."],
  baute_v_coffee: ['baute', "Sit. Please. Sit with me a moment. The cloud is beautiful from here."],
  baute_v_02: ['baute', "You wrote in your thesis that a baptised bell is a voice the dead can hear. I read it three times. You were right."],
  baute_v_03: ['baute', "This is ours. The priestesses made it. Every summer the sun says the same prayer through that hole, and the sea stays down."],
  vasco_v_07a: ['vasco', "And you're taking the prayer apart."],
  vasco_v_07b: ['vasco', "Rayco. What's in the vault?"],
  baute_v_04: ['baute', "In 1966 I was twenty-six, with a new degree and no power at all. I stood there and watched them bulldoze the burial ground above my grandmother's village for a hotel. My great-great-grandparents were under it. They put the bones in a skip. [pause] The site manager was a young man called Ignacio Montesdeoca. Now he sponsors my dig, and shakes my hand at dinners."],
  baute_v_05: ['baute', "I've spent thirty years filing objections. I've lost every one. [pause] The island has asked politely for five hundred years, Vasco."],
  baute_v_06: ['baute', "I need one number from you. The angle for the last disc, so that on San Juan morning it sends the light the wrong way. The sea will take back the south coast. The concrete. Not us."],
  vasco_v_08: ['vasco', "It doesn't take orders, Rayco."],
  baute_v_07: ['baute', "Mine will."],
  vasco_v_09a: ['vasco', "Elena worked this out too. Didn't she."],
  vasco_v_09b: ['vasco', "Where's Dr. Suárez, Rayco?"],
  baute_v_08: ['baute', "[pause] I took out one disc. One. The night before she drove down."],
  baute_v_09: ['baute', "I didn't touch her. The sea came for her because she understood it. I didn't know it did that. [pause] I know now."],
  vasco_v_10: ['vasco', "Then you know what it will do. To anyone who gets in its way. To the people on the beaches."],
  baute_v_10: ['baute', "[pause] The number, Vasco."],
  vasco_v_11: ['vasco', "No."],
  baute_v_11: ['baute', "[pause] I thought you'd say that. You're a better man than me. It's very inconvenient."],
  baute_v_see: ['baute', "Come and see the discs, at least. So you know they're safe. They're in the old granary."],
  vasco_v_walk: ['vasco', "No. I'm walking down to Artenara. Someone has to know. [pause] Keep your coffee, Rayco."],
  narr_v_drug: ['narr', "Three hundred metres down the road, the coffee takes hold: Elena's back sedative, from the camp kit. Yeray and Baute carry him to the granary under the caves. He wakes on the steps behind a locked grille, with a headache and the taste of cinnamon."],
  baute_v_12: ['baute', "I'm sorry. [pause] I'll come for you on Monday. You have my word."],
  vasco_v_12: ['vasco', "Your word's under a hotel, Rayco."],
  narr_v_silence: ['narr', "Baute's footsteps fade. Silence. A pocket torch, a dying battery, and a Saturday to think in."],
  vasco_look_crates: ['vasco', "Five crates, an obsidian disc in each, wrapped in cloth. The missing nails. All here. [pause] Five out, two still in the cave. Tomorrow he takes the sixth."],
  vasco_look_walls: ['vasco', "Pick marks. Nine hundred years old. Someone cut this in a hurry. [pause] And low behind the last crate, worn almost away: a coiled serpent. [pause] Seven coils."],
  vasco_look_grille: ['vasco', "Nineteenth-century iron, new padlock. Rayco always did respect the original fabric. [pause] The top's in hard basalt. The bottom's leaded into the soft tuff of the threshold. The lead's gone to powder."],
  vasco_look_anchor: ['vasco', "A bottom anchor of the grille, leaded into soft tuff. If both come out, the grille might swing out at the bottom on its chain. Like a cat flap. Alan would like that."],
  vasco_dig_hands: ['vasco', "Not with my fingernails. Not yet."],
  vasco_dig_1: ['vasco', "The lead crumbles. Slowly. Torch off. Save it. Dig by feel."],
  vasco_dig_2: ['vasco', "Nearly. A centimetre of lead and a lot of nerve."],
  vasco_dig_left_out: ['vasco', "Out. One anchor out. [pause] Before the other one, something for whoever comes."],
  vasco_anchor_out: ['vasco', "That one's out."],
  vasco_right_first: ['vasco', "The left one first. One thing at a time. Lorenzo used to say I dig like I pray: in order."],
  vasco_right_first_mark: ['vasco', "Before I start on the other. Something on the wall, for whoever comes. In case."],
  vasco_look_wallbit: ['vasco', "Soft rock by the grille, at eye height. You could write on it with a trowel."],
  vasco_mark_early: ['vasco', "Dig first. Write if there's time. There's always time to write, my mother says. She means letters of complaint."],
  vasco_mark_1_scratch: ['vasco', "Twenty-three degrees, twenty-six minutes. The closing angle. Not the other one. Never the other one."],
  vasco_mark_a: ['vasco', "[pause] And underneath. A."],
  vasco_mark_done: ['vasco', "It's there. Whoever comes."],
  vasco_look_mark: ['vasco', "23° 26′. And an A. [pause] The most I can say, after Friday."],
  vasco_wet_1: ['vasco', "My knees are wet. [pause] Salt water. On the floor of a granary a thousand metres up. And rising."],
  vasco_wet_2: ['vasco', "Elena read the cave right, and it came for her that night. This morning I read it right too. [pause] Keep digging."],
  vasco_dig_right_1: ['vasco', "It's at my waist. It doesn't spill through the bars. It stays with me, wherever I stand. Like a dog. Keep digging."],
  vasco_anchor_cm: ['vasco', "A centimetre. One centimetre of lead and no blade left."],
  vasco_snap: ['vasco', "[pause] The blade. Lorenzo's blade, snapped. A centimetre left. [pause] Of course."],
  vasco_v_13: ['vasco', "Pai nosso, que estais no céu... [pause]"],
  vasco_v_14: ['vasco', "I'm sorry. I've been working on a Saturday. [pause] I know You're busy."],
  vasco_v_15: ['vasco', "[pause] If You can't come... send the idiot."],

  // ================================================================ SUNDAY 23 JUNE: the choice
  alan_su_wake: ['alan', "Sunday. San Juan's eve. The plane home is at four. Vasco hasn't called. Vasco can't call."],
  alan_su_choice: ['alan', "The airport, and Lisbon, and Pessoa, and never knowing. Or Carmen's door, and admitting I'm an idiot to a woman who already knows."],
  alan_choose_airport: ['alan', "Go to the airport."],
  alan_choose_carmen: ['alan', "Go to Carmen's."],
  alan_su_carmen: ['alan', "Joaquim ran. My grandfather ran, and spent forty years being sorry in a ledger. [pause] Triana. Carmen's."],
  alan_su_airport: ['alan', "Gando. Four o'clock. It's easy. Everything about leaving is easy."],
  clerk_1: ['clerk', "Lisbon? Window or aisle?"],
  alan_su_clerk: ['alan', "[pause] Window."],
  clerk_2: ['clerk', "Lovely. Boarding at three-thirty. Have a good flight, señor."],
  narr_bad_1: ['narr', "From the window of the plane, the island lies under its grey lid, and the lid has a black stain spreading in it, over the city."],
  narr_bad_2: ['narr', "That night Las Palmas goes down to the sea for San Juan, as it always has."],
  narr_bad_3: ['narr', "In the morning, on a mountain above the cloud, there is no one in the vault at all. Only salt on the steps."],
  carmen_su_door: ['carmen', "[pause] You didn't go home."],
  alan_su_idiot: ['alan', "I'm an idiot. I've been an idiot all week. It was Baute, not Montesdeoca, and Vasco's up there, and nobody's heard from him since yesterday. Please."],
  carmen_su_idiot: ['carmen', "Everybody's an idiot, cariño. Come in before you say it to the neighbours."],
  alan_look_carmen_flat: ['alan', "Carmen at home: no sunglasses, an ashtray, a bottle of wine she hasn't opened. She looks smaller here. Everyone does, at home."],
  alan_look_machine: ['alan', "An answering machine, the red light blinking. One message. She's never erased it. You can tell."],
  alan_look_machine_2: ['alan', "The red light's still blinking. She'll never erase it. I wouldn't."],
  alan_su_machine: ['alan', "Carmen. The message on your machine. Is it Elena?"],
  carmen_su_dont: ['carmen', "Don't. [pause] I haven't played it since December. Six months."],
  alan_su_please: ['alan', "Please. I think she said what I've been trying to say all week, and she said it better."],
  carmen_su_after: ['carmen', "[pause] 'It's a door.' [pause] She called me, and I was asleep, and I heard it in the morning, after the Guardia rang."],
  alan_su_after: ['alan', "She was right. Somebody's opening it. It's Baute. And on San Juan morning, it opens."],
  carmen_su_box: ['carmen', "Her things are in the box by the door. Her notebook. The Guardia's photographs. I couldn't open it. You open it."],
  carmen_su_again: ['carmen', "Once was enough."],
  alan_look_elena_box: ['alan', "A shoebox. 'E.' on the lid in marker. Everything left of a woman fits in a shoebox. It never seems right."],
  alan_su_box: ['alan', "Her notebook. And a photograph from the Guardia Civil."],
  alan_su_triangle: ['alan', "The triangle on the windscreen. The same as the arrows on the cave wall. She drew it while the water came up. She was telling us where."],
  alan_su_triangle_2: ['alan', "A triangle, point down, drawn in salt on a windscreen. She was telling someone something."],
  alan_box_again: ['alan', "I've got them. I'll bring them back. I'll bring everything back."],
  alan_look_fridge: ['alan', "A fridge with wine, olives, gofio and six bottles of water. A woman who keeps water by the litre, for a car that drinks it."],
  alan_take_water: ['alan', "Two litres of water. For the radiator, or for me, whichever boils first."],
  alan_fridge_again: ['alan', "I've got water. More would just slosh."],
  alan_look_carmen_window: ['alan', "Triana's rooftops, and beyond them, the sea, and on the sea, the bonfires being built for tonight."],
  alan_look_carmen_shelves: ['alan', "Books about the island, and a framed photograph of two women laughing on a mountain. One of them is Carmen. The other is Elena."],
  alan_su_not_leaving: ['alan', "Not yet. Not without knowing where he is."],
  alan_su_go: ['alan', "The Land Rover's downstairs. Carmen has the keys. Let's go."],
  carmen_su_wait: ['carmen', "Give me a minute. I'm deciding whether to throw you out."],
  alan_su_where: ['alan', "Where's Vasco?"],
  alan_su_where_early: ['alan', "I don't know enough yet. Elena knew. Let me read what Elena knew."],
  alan_su_think_1: ['alan', "Nieves has no message. The dig radio's dead: somebody took the fuse. And Yeray's words, in Rafa's sketchbook: the discs go down to the lower vault at night, and only Rayco has the key."],
  alan_su_think_2: ['alan', "Vasco read the lock. He'd refuse Baute anything he needed for it. And Baute puts the things he can't let go of in one place."],
  alan_su_vasco_camp: ['alan', "He's at the camp, sulking. With the radio off."],
  carmen_su_camp_no: ['carmen', "Vasco doesn't sulk with the radio off. Vasco sulks with the radio on, so you can hear him not calling."],
  alan_su_vasco_lisbon: ['alan', "He's gone home. To Lisbon. Without me."],
  carmen_su_lisbon_no: ['carmen', "His bags are at your hotel, cariño. Nobody leaves without their trowels."],
  alan_su_vasco_vault: ['alan', "In the lower vault. Under the caves. With the discs."],
  carmen_su_vault: ['carmen', "[pause] The old granary. The grille. Rayco had a padlock put on it in May. For 'security'."],
  alan_su_sea_too: ['alan', "And the letter says the Sea strikes first at whoever understands the lock. Elena understood it. Vasco understands it. [pause] It's coming for him. Tonight."],
  carmen_su_go: ['carmen', "[pause] Get your shoes on. We're going up."],
  carmen_su_water: ['carmen', "And bring water from the fridge. The radiator drinks more than I do."],
  alan_ask_carmen_elena_su: ['alan', "Tell me about her."],
  carmen_su_elena: ['carmen', "She laughed at everything. She drew everything. She left her socks in the bath for eight years. [pause] We were going to buy a house in Artenara. Above the cloud."],
  alan_ask_carmen_radiator: ['alan', "Will the Land Rover make it up the mountain?"],
  carmen_su_radiator: ['carmen', "It's made it up for nineteen years. Faith, water and swearing. You bring the water."],
  alan_bye_carmen_su: ['alan', "Give me a moment."],
  carmen_su_keys: ['carmen', "Keys. Water. Shoes. Go."],
  carmen_su_think: ['carmen', "Think faster."],
  carmen_su_drawing: ['carmen', "[pause] Rafa's hand. Everyone in Vegueta has one. [pause] Oh, cariño."],
  carmen_su_lets_go: ['carmen', "Vámonos."],
  // the Land Rover
  narr_lr_1: ['narr', "Dusk on the mountain road. The Land Rover climbs the hairpins into the black mist, and then into the panza de burro, and the world goes grey and blind."],
  carmen_lr_1: ['carmen', "Talk to me. I can't see the road. If you talk, I'll know I'm not dead."],
  alan_lr_1: ['alan', "I slept with a twenty-three-year-old painter on Friday night and lied to him about Vasco, and I haven't told Vasco, and he might be drowning in a granary."],
  carmen_lr_2: ['carmen', "[pause] Okay. Talk about something else."],
  alan_look_carmen_driving: ['alan', "Carmen, both hands on the wheel, a cigarette unlit in her mouth. The lighter's in her pocket. She hasn't the hands free for it."],
  carmen_lr_talk: ['carmen', "Eyes on the road. You see it before I do, shout."],
  carmen_lr_boil: ['carmen', "Mierda. [pause] The temperature. She's boiling."],
  carmen_lr_water: ['carmen', "Water. On the radiator. Now, before she cracks. I'm not stopping in this cloud."],
  carmen_lr_boil_talk: ['carmen', "Water, Alan!"],
  alan_lr_gauge: ['alan', "The temperature gauge. Climbing with us."],
  alan_lr_gauge_red: ['alan', "In the red. Past the red. In a part of the gauge they don't paint."],
  alan_lr_steam: ['alan', "Steam out of the bonnet, white in the black. She's boiling. I need water on it."],
  alan_lr_fill: ['alan', "Out of the window, half of me in the cloud, pouring water into a boiling radiator at thirty kilometres an hour. Inês would be so proud. Inês would be so angry."],
  carmen_lr_go: ['carmen', "She's cooling. Good girl. Good girl. Hold on."],
  alan_lr_feet: ['alan', "Carmen. [pause] My feet are wet. There's water in the footwell. Salt. It's rising."],
  carmen_lr_through: ['carmen', "Then we drive through it. Hold your breath and talk."],
  alan_lr_footwell: ['alan', "Black water round my ankles. It knows me. I can feel it knowing me."],
  narr_lr_stars: ['narr', "And then the Land Rover breaks out of the top of the cloud into a clear night full of stars."],
  carmen_lr_bonfires: ['carmen', "Look down."],
  alan_lr_bonfires: ['alan', "The whole coast. The cloud's glowing orange underneath, where the bonfires are. A whole city, lighting fires for the shortest night. [pause] It doesn't know what it's welcoming."],
  carmen_su_here: ['carmen', "The camp. No lights. Rayco's at the cave, waiting for the sun. The granary steps are past the finds table."],
  alan_su_vault_where: ['alan', "Stay with the car. If I'm not back, shout. Loudly. Swear, if it helps."],
  alan_look_carmen_camp: ['alan', "Carmen by the Land Rover, lighting a cigarette on the third try, watching the cave mouth."],
  carmen_su_camp: ['carmen', "Go. I'm watching Rayco. I'm good at watching Rayco. I've had twenty years."],
  alan_look_cloud_night: ['alan', "The sea of cloud by starlight, orange underneath where the city's burning its bonfires."],
  alan_look_cloud_mon: ['alan', "The sun on the sea of cloud. The most beautiful thing I've ever seen, and I can't look at it for long. I have work."],
  alan_look_finds_camp: ['alan', "The finds table under its tarpaulin. Labels, trays, a thermos. Baute's thermos. I'm not drinking anything up here."],
  alan_radio_dead: ['alan', "The camp radio. No fuse. Dead as a door."],
  alan_radio_mon: ['alan', "The radio's alive. The Guardia are coming. Everything's coming."],
  // the vault, Sunday night
  narr_vault_su: ['narr', "The granary vault. A torch on the floor. Behind the grille, the water to Vasco's mouth, and not one drop through the bars. In front of it, Yeray, with a pick, levering at the last anchor."],
  yeray_su_1: ['yeray', "Doctor! Hold on! It's coming, it's nearly coming!"],
  vasco_su_1: ['vasco', "[pause] You took your time."],
  alan_su_vasco_1: ['alan', "I came by Land Rover. With a woman who swears. [pause] Hello."],
  alan_look_vasco_vault: ['alan', "Vasco, chin up, the water at his lips, and he's still the calmest man in the room."],
  vasco_su_vault: ['vasco', "Talk less. Pull."],
  alan_look_yeray_vault: ['alan', "Yeray. The boy from the bar. He came down with bread and water, and stayed with a pick."],
  yeray_su_pull: ['yeray', "The grille! Pull the grille when I lever! Together!"],
  yeray_su_after: ['yeray', "I helped him carry the doctor down here. Saturday. [pause] I'll tell the Guardia. All of it."],
  alan_look_grille: ['alan', "The grille. One bottom anchor gone, the other a centimetre from giving. Yeray's pick in the gap."],
  alan_look_grille_off: ['alan', "The grille, hanging by its chain. We did that. Three idiots and a pick."],
  alan_su_pull: ['alan', "Now, Yeray!"],
  yeray_su_2: ['yeray', "Again! ¡Otra vez!"],
  narr_grille: ['narr', "The last anchor tears out of the tuff. The grille swings out at the bottom on its chain like a cat flap, and Alan pulls Vasco through by his collar. The water stays behind the bars. Then it sinks away into the floor, as if it had never been there."],
  vasco_su_out_1: ['vasco', "[pause] A cat flap. I said a cat flap. I said you'd like that."],
  alan_su_out_1: ['alan', "You were talking to yourself about me?"],
  vasco_su_out_2: ['vasco', "All night. You were very annoying. [pause] He's at the cave. Six discs out. The seventh he's set by guesswork. At sunrise it opens."],
  alan_su_out_2: ['alan', "Then we close it. You know how."],
  vasco_su_out_3: ['vasco', "I know where the light has to fall. Somebody has to put the discs back from inside the water. [pause] Not you."],
  alan_su_mark: ['alan', "On the wall by the grille: 23° 26′. And under it, an A. [pause] I don't make a joke."],
  alan_look_mark: ['alan', "23° 26′. A."],
  alan_look_walls: ['alan', "Pick marks, old as anything. And low down, behind a crate, a coiled snake carved in the rock. Vasco looks at it and says nothing. So I say nothing."],
  alan_look_crates: ['alan', "Five crates. In each, a black glass disc wrapped in cloth. The nails Baute pulled out."],
  alan_crates_first: ['alan', "Vasco first. Then the discs. In that order, always, from now on."],
  alan_crates_empty: ['alan', "Empty now. Good."],
  alan_su_discs: ['alan', "Five discs. Heavy, cold, and my reflection in every one of them, looking frightened."],
  vasco_su_discs: ['vasco', "Five. Rayco has the sixth. The seventh never left its socket."],
  vasco_su_dawn: ['vasco', "Sunrise is at six fifty. We have until the beam."],
  carmen_su_dawn: ['carmen', "Then come on, the pair of you. The sun doesn't wait for anyone. That's the whole point of it."],
  alan_vault_not_without: ['alan', "Not without Vasco."],
  alan_vault_discs: ['alan', "The discs. We'll need them. All of them."],

  // ================================================================ MONDAY 24 JUNE: San Juan
  narr_cave_mon: ['narr', "Cave 6, before sunrise. Six sockets empty. The seventh disc turned to Baute's own reckoning of the door. And seawater rising through the floor of a cave a thousand metres above the sea."],
  baute_m_1: ['baute', "[pause] Vasco. You're out. [pause] Good. I'm glad. I am."],
  vasco_m_1: ['vasco', "Turn it back, Rayco. Look at the floor. It isn't going to the south coast. It's coming here first."],
  baute_m_2: ['baute', "It will do what it's asked. It always has."],
  alan_m_1: ['alan', "It never has. Ask the women in white. Ask Vicente Lacerda. Ask anyone it ever did a favour for."],
  vasco_m_halves: ['vasco', "Two halves. I know where every disc has to sit, and the seventh's angle, and I have to stay on the floor and read the light to call them."],
  vasco_m_who: ['vasco', "And someone has to stand in the water at the door, at the sockets, and put them back. While it rises. [pause] I'll find a way to do both."],
  alan_m_coming: ['alan', "You can't do both."],
  vasco_m_no: ['vasco', "Alan. No."],
  alan_m_anyway: ['alan', "It's coming for me anyway. I'd rather it found me doing something useful."],
  narr_m_quiet: ['narr', "Alan steps down into the water at the door in the floor. It knows him. It goes quiet, and waits for him to slip."],
  vasco_m_ready: ['vasco', "Listen to me, and only me. One at a time. In the order I say."],
  vasco_m_door: ['vasco', "The door's there, in the floor. Whoever stands in it can reach the channel from the ladder. [pause] Not you."],
  alan_look_vasco_cave: ['alan', "Vasco on the floor of the cave with chalk, a clinometer and Elena's charts, reading the light like a page."],
  alan_look_carmen_mirror: ['alan', "Carmen at the cave mouth, with the shaving mirror from the Land Rover. She's thought of everything. She's had six months to think."],
  alan_look_yeray_cave: ['alan', "Yeray, at the back, very pale. He'll be all right. He doesn't know that yet."],
  alan_look_baute_cave: ['alan', "Baute by the seventh socket, the sixth disc in his hand, very still. The pendant at his throat."],
  alan_look_door: ['alan', "A round dark place in the cave floor. The great triangle points at it. The door."],
  alan_look_door_in: ['alan', "I'm in it to my waist. It's cold. It's patient. It's very, very patient."],
  alan_m_in_already: ['alan', "I'm in. I'm not getting out until it's shut."],
  alan_m_no_discs: ['alan', "Not with empty hands. The discs."],
  alan_socket_empty: ['alan', "An empty socket in the channel, worn smooth by nine hundred summers."],
  alan_socket_set: ['alan', "That one's back. Black glass in old stone."],
  alan_look_seventh: ['alan', "The seventh disc, still in its socket, turned to Baute's angle. Wrong."],
  alan_look_seventh_set: ['alan', "Twenty-three degrees, twenty-six minutes. The tilt of the world."],
  alan_look_discs: ['alan', "Obsidian. The nails. I'm putting the nails back."],
  alan_look_disc6: ['alan', "The sixth disc. Warm from Baute's hand."],
  vasco_call_1: ['vasco', "The fourth socket from the mouth. Fourth. Now."],
  vasco_call_2: ['vasco', "First socket. The one nearest the mouth."],
  vasco_call_3: ['vasco', "Fifth."],
  vasco_call_4: ['vasco', "Second. The second socket, Alan."],
  vasco_call_5: ['vasco', "Sixth. Next to the seventh."],
  vasco_call_6: ['vasco', "The last empty one. The third. Rayco's disc."],
  vasco_m_good_1: ['vasco', "Good. The beam's moved. Breathe."],
  vasco_m_good_2: ['vasco', "Good."],
  vasco_m_good_3: ['vasco', "Yes. It's following. It's following the triangles."],
  vasco_m_good_4: ['vasco', "Good. Two more and the seventh."],
  vasco_m_good_5: ['vasco', "Five. That's all we have."],
  vasco_m_good_6: ['vasco', "Six. Now the seventh. Turn it. Twenty-three, twenty-six."],
  vasco_m_wrong_1: ['vasco', "No, no, no! Wrong one. It surged. Listen to me, Alan. Only me."],
  vasco_m_wrong_2: ['vasco', "Alan! It's at your chest. Please. Listen."],
  narr_m_drown: ['narr', "The water rises over the ladder, and over the man on it, and goes quiet."],
  narr_m_cloud: ['narr', "A cloud crosses the sun. The beam fades from the wall."],
  vasco_m_light: ['vasco', "I've lost the light! I can't read it without the light!"],
  alan_m_carmen_light: ['alan', "Carmen! The mirror! Give him the light!"],
  carmen_m_mirror: ['carmen', "Got it. [pause] Read fast, I've only got two hands."],
  carmen_m_holding: ['carmen', "I'm holding it. My arm's going to fall off. Hurry."],
  carmen_m_1: ['carmen', "Do what he says. For once in your life, do exactly what somebody says."],
  vasco_m_six: ['vasco', "Six. We need six. Rayco has the sixth."],
  baute_m_stain_1: ['baute', "[pause] Look. Through the mouth. Look at the cloud."],
  baute_m_stain_2: ['baute', "There's a black stain spreading through it. Over Las Palmas. Over La Isleta, over Vegueta. Over my own people. [pause] The south is clear. The hotels are in the sun."],
  baute_m_stain_3: ['baute', "It was never going to listen. Was it."],
  baute_m_listen: ['baute', "Here. [pause] The sixth. I kept it back for myself. For when it was done."],
  vasco_m_thank: ['vasco', "Thank you, Rayco."],
  baute_m_hold: ['baute', "I know what you're going to say. Everyone has always known what to say to me."],
  baute_m_given: ['baute', "I've given it. That's all I have left to give."],
  yeray_m_1: ['yeray', "I took the radio fuse. Saturday. He told me to. [pause] I've still got it. I've got it in my pocket."],
  vasco_m_seventh: ['vasco', "The seventh. Turn it back. Twenty-three degrees, twenty-six minutes."],
  vasco_m_seventh_wait: ['vasco', "Not yet. The six first. It only works in order."],
  vasco_m_seventh_how: ['vasco', "Turn it until I say. To the closing angle."],
  narr_m_beam: ['narr', "The disc turns. The beam bends, and falls true across the triangles, one after another, down the wall, to the centre of the great triangle."],
  vasco_m_true: ['vasco', "It's true. It's falling true. [pause] Alan, get out of the water. Get out now!"],
  narr_m_drag: ['narr', "The lock shuts. The water drains back through the door in the floor, and takes whatever is standing in it. It drags Alan off the ladder, down into the dark, as it took the priestess. And he stops fighting."],
  vasco_m_hold: ['vasco', "No. [pause] No, you don't."],
  narr_m_chain: ['narr', "Vasco has his wrist and won't let go. Carmen has Vasco. Yeray has Carmen. Baute has Yeray. The priestess died because she was alone in the water. Alan lives because he isn't."],
  vasco_m_twice: ['vasco', "I've let go of people before. I wasn't going to do it twice."],
  narr_m_breath: ['narr', "The water draws back into the rock with a sound like a breath. Far below, through the cave mouth, the sea flattens, and for a moment something enormous settles beneath it."],
  narr_m_sunrise: ['narr', "The sun rises over the sea of cloud. Below, the black mist sinks back and is gone. Only the ordinary grey of the panza de burro is left over the city."],
  carmen_m_after: ['carmen', "[pause] Somebody give me a cigarette. Somebody give me a lighter that works."],
  yeray_m_after_1: ['yeray', "Is it over? Doctor, is it over?"],
  alan_m_after: ['alan', "I'm wet. I'm alive. I'm wet and alive. [pause] It's over."],
  yeray_m_fuse: ['yeray', "Here. The radio fuse. I took it on Saturday. I'm sorry. I'm so sorry. Call whoever you have to call."],
  alan_m_fuse: ['alan', "Thank you, Yeray. You came back down with bread and a pick. That counts."],
  yeray_m_after: ['yeray', "I'll tell them. All of it."],
  carmen_m_fuse: ['carmen', "Yeray's got the radio fuse. Get it in the radio and I'll call the Guardia. Rayco's waiting for them. Look at him. He's waiting."],
  carmen_m_guardia_done: ['carmen', "They're coming. Go and talk to your man. Go."],
  baute_m_after: ['baute', "[pause] When the Guardia come, I'll go with them. I'd like to walk down to the car on my own feet."],
  baute_m_turn_in: ['baute', "I'll go down with them. I opened the door. I'll answer for who came through it. [pause] Pepe Santana. Agustín Ramos. Elena. [pause] I'll say their names."],
  alan_m_fuse_in: ['alan', "The fuse in. A crackle, a hiss, and a voice from Artenara saying 'Diga'."],
  carmen_m_radio: ['carmen', "Give me that. [pause] Guardia Civil, Artenara. This is Dr. Carmen Trujillo, at Risco Caído. I have a man here who wants to turn himself in. [pause] No, I'm not joking. When do I joke?"],
  carmen_m_guardia: ['carmen', "They're coming up. An hour. [pause] I'll ride down with him. Somebody should."],
  // the confession
  alan_m_ask_hurt: ['alan', "Are you hurt?"],
  vasco_m_hurt: ['vasco', "My knees are thirty years older than they were on Saturday. My hands are full of tuff. [pause] I'm all right. You held on. I held on."],
  alan_m_ask_monte: ['alan', "The map. I thought it was Montesdeoca."],
  vasco_m_monte: ['vasco', "He ran the bulldozers in sixty-six. Over Rayco's grandmother's dead. He's guilty of that. Not of this. [pause] Most people are guilty of something. Not usually of the thing you're looking for."],
  alan_m_later: ['alan', "Nothing. Later."],
  vasco_m_later: ['vasco', "Later is when things go wrong with us. You know that."],
  alan_m_confess: ['alan', "Vasco. I have to tell you something. Before you ask."],
  alan_m_confess_1: ['alan', "On Friday night, after you left. [pause] There was a bar. A painter. I went home with him."],
  alan_m_plain: ['alan', "That's it. That's all of it. I lied to him, and I didn't tell you first, and I'm telling you now."],
  alan_m_plain_2: ['alan', "No excuses. I could think of some. I'm not going to say them."],
  vasco_m_plain_1: ['vasco', "[pause] Yeray said there was a Portuguese guy at Rafa's bar. Funny. Sad. [pause] I knew. I didn't want to."],
  alan_m_excuses: ['alan', "You'd left. I was drunk. I thought we were over. I thought you'd gone."],
  alan_m_excuses_2: ['alan', "You'd walked out. It was the solstice. I'd had five rums. I was trying not to think, and I'm very good at that."],
  narr_m_silence: ['narr', "Vasco says nothing for a long time. The sun climbs a finger's width over the cloud."],
  vasco_m_excuses_1: ['vasco', "[pause] I know I left. I know about the rum. [pause] That's not the bit that hurts."],
  alan_m_blame: ['alan', "And it's all my fault. Everything. The desk, the fight, the bar. I'm a disaster. I don't deserve you. You should go."],
  alan_m_blame_2: ['alan', "I'm the worst thing that's ever happened to you. Worse than the Church. Worse than Rome."],
  vasco_m_blame_1: ['vasco', "Stop. [pause] Don't make it so big that I have to comfort you. That's another kind of door, Alan. Stay in the room."],
  vasco_m_first: ['vasco', "[pause] Thank you for telling me first."],
  vasco_m_yeray: ['vasco', "It isn't all right. Not today. Ask me again in a while."],
  alan_m_yeray: ['alan', "I will. I'll keep asking."],
  vasco_m_trowel_1: ['vasco', "Here. [pause] Lorenzo's. Half the blade's in the vault. 'For the day you find something worth keeping.'"],
  vasco_m_trowel_2: ['vasco', "[pause] Keep it."],
  alan_m_trowel: ['alan', "[pause] I'll keep it."],
  alan_look_fuse: ['alan', "The camp radio's fuse. A glass tube the size of my thumb. Yeray carried it in his pocket for two days, like a sin."],
  alan_look_trowel: ['alan', "A small silver trowel with half its blade gone. The most romantic thing anyone's ever given me, and it's broken. That seems right."],
  vasco_m_after: ['vasco', "Go and help Carmen with the radio. I need a minute with the sun."],
  vasco_m_after_trowel: ['vasco', "The Guardia, then the road down. Then we'll see."],
  // the ending
  carmen_m_ride: ['carmen', "I'll ride down with Rayco in the Guardia car. Somebody should. I'll visit. I'll bring him cigarettes he can't smoke."],
  carmen_m_keys: ['carmen', "Take the Land Rover. Don't boil her. [pause] And Alan. Bring it back. Bring yourselves back too."],
  narr_end_road: ['narr', "The road down, in Carmen's Land Rover. Alan drives. Above them the sun; below them the cloud, and under the cloud the city, which doesn't know."],
  vasco_end_hand: ['narr', "On a hairpin bend, Vasco puts his hand over Alan's on the gearstick, and leaves it there."],
  narr_end_plain: ['narr', "It isn't forgiveness. It's something better: a man who stays in the room."],
  narr_end_excuses: ['narr', "It isn't forgiveness. It's careful, and quiet, and it's a start."],
  vasco_end_last: ['vasco', "[pause] Ask me again in Santo Domingo."],
  narr_end_fireworks: ['narr', "That evening, Las Palmas celebrates five hundred and eighteen years with fireworks over Las Canteras. It doesn't know it nearly didn't have them."],
  narr_love_2_warm: ['narr', "The last night: quieter than the first. Not forgiveness. A choice, made twice."],
  narr_love_2_quiet: ['narr', "The last night: careful, and quiet, and close. A choice, made slowly."],

  // ================================================================ Inês's hints ("What now?")
  ines_hint_jacket: ['ines', "A jacket? In a hotel? Hotels are full of things people left behind. Ask nicely. Be the sort of man who'd own whatever you find."],
  ines_hint_nieves: ['ines', "So the English lady told you whose blazer it is. Then describe it to the receptionist like it's yours. Down to the pocket."],
  ines_hint_reception: ['ines', "You have a jacket. Go to the museum. Meet the professor. Be charming. You know how. You were born doing it."],
  ines_hint_call_first: ['ines', "You've got a jacket and an hour. Ring me from the box on the beach before you go, I want to hear about the boyfriend."],
  ines_hint_hotel: ['ines', "Go back to your hotel. Go to Vasco. And tell him about the mist. [pause] No? Fine. Go to him anyway."],
  ines_hint_isleta: ['ines', "If the sea's acting strangely, ask the people who live off it. Find the fishermen. Find the oldest one."],
  ines_hint_cathedral: ['ines', "Every city has a cathedral and every cathedral has a sacristan who knows everything. Find him. Make yourself useful."],
  ines_hint_bell: ['ines', "You wound a clock? Look at the bells while you're up there. Bells are our family business, God help us."],
  ines_hint_fax: ['ines', "Fax me what you found. Your hotel has a fax. Hotels always have a fax. Give it to the woman with the eyebrow."],
  ines_hint_museum: ['ines', "Go and see the museum archive. There's always a list on a board somewhere. Read the boring things. That's where they hide the interesting things."],
  ines_hint_wed_done: ['ines', "You've done enough for one day. Go and eat something. Go back to the hotel."],
  ines_hint_carmen_lore: ['ines', "The archivist. She knows the island's history and she knows something about your mist. Go back. Take cigarettes."],
  ines_hint_colon: ['ines', "Go and see the Castilian side. Columbus's house. The lady with the glasses."],
  ines_hint_guard: ['ines', "The guard at the dinner? Guards move for two things: their boss, and trouble. Find some trouble. Preferably someone else's."],
  ines_hint_desk: ['ines', "A locked drawer and a dinner table full of knives. I'm not telling you that. I'm telling you nothing. I'm in Lisbon."],
  ines_hint_thu_done: ['ines', "Go to bed. Say sorry. Mean it."],
  ines_hint_carmen_fri: ['ines', "Go to Carmen. Do something useful with the ache."],
  ines_hint_fri_night: ['ines', "Go and have one drink. One, Alan. And then go back to the hotel and call me."],
  ines_hint_fax_sat: ['ines', "Go to your hotel. The fax. Read it sitting down."],
  ines_hint_isleta_sat: ['ines', "Doña Pino. The list. If the Sea's collecting tonight, she's on it. Go to La Isleta."],
  ines_hint_general: ['ines', "Go to him, Alan."],
};
